function normalizeQuote(q) {
  if (q.prendas) return q;
  const prenda = {
    id: uid(), nombre: q.prenda || 'Prenda 1',
    itemsConUnidad: q.itemsConUnidad || [], itemsDirectos: q.itemsDirectos || [],
    corte: q.corte || '0', corteReal: q.corteReal || '', corteFactura: q.corteFactura || '',
    ensamble: q.ensamble || '0', ensambleReal: q.ensambleReal || '', ensambleFactura: q.ensambleFactura || '',
    margenError: q.margenError || '0.5', margenGanancia: q.margenGanancia || '30', comision: q.comision || '20',
    envio: q.envio || '', descuento: q.descuento || '', impuesto: q.impuesto || '', gValenthina: q.gValenthina || '',
  };
  return {
    id: q.id, fecha: q.fecha, clientId: q.clientId || '', clienteNombre: q.clienteNombre || '',
    asesor: q.asesor || '', estado: q.estado || 'Sin definir', notas: q.notas || '',
    prendas: [prenda], orderIds: q.orderId ? [q.orderId] : [], createdAt: q.createdAt,
  };
}
function sumItems(items) { return items.reduce((s, i) => s + (Number(i.unidades) || 0) * (Number(i.valorUnidad) || 0), 0); }
function sumDirect(items) { return items.reduce((s, i) => s + (Number(i.valor) || 0), 0); }
function computePrendaTotals(p) {
  const totalBase = sumItems(p.itemsConUnidad) + sumDirect(p.itemsDirectos);
  const mError = totalBase * ((Number(p.margenError) || 0) / 100);
  const totalInsumos = totalBase + mError;
  const corte = Number(p.corte) || 0, ensamble = Number(p.ensamble) || 0;
  const totalProduccion = totalInsumos + corte + ensamble;
  const gananciaBruta = totalProduccion * ((Number(p.margenGanancia) || 0) / 100);
  const comisionValor = gananciaBruta * ((Number(p.comision) || 0) / 100);
  const gananciaNeta = gananciaBruta - comisionValor;
  const envio = Number(p.envio) || 0, descuento = Number(p.descuento) || 0, impuesto = Number(p.impuesto) || 0, gValenthina = Number(p.gValenthina) || 0;
  const totalPrenda = totalProduccion + gananciaBruta + envio - descuento + impuesto + gValenthina;
  return { totalBase, mError, totalInsumos, corte, ensamble, totalProduccion, gananciaBruta, comisionValor, gananciaNeta, totalPrenda };
}
function computeQuoteTotals(q) {
  return q.prendas.reduce((acc, p) => {
    const t = computePrendaTotals(p);
    Object.keys(t).forEach(k => { acc[k] = (acc[k] || 0) + t[k]; });
    return acc;
  }, {});
}
function computeRealTotals(p) {
  let cot = 0, real = 0, count = 0;
  p.itemsConUnidad.forEach(it => {
    if (it.valorReal !== '' && it.valorReal != null) {
      cot += (Number(it.unidades) || 0) * (Number(it.valorUnidad) || 0);
      real += Number(it.valorReal) || 0; count++;
    }
  });
  p.itemsDirectos.forEach(it => {
    if (it.valorReal !== '' && it.valorReal != null) {
      cot += Number(it.valor) || 0; real += Number(it.valorReal) || 0; count++;
    }
  });
  if (p.corteReal !== '' && p.corteReal != null) { cot += Number(p.corte) || 0; real += Number(p.corteReal) || 0; count++; }
  if (p.ensambleReal !== '' && p.ensambleReal != null) { cot += Number(p.ensamble) || 0; real += Number(p.ensambleReal) || 0; count++; }
  return { cot, real, diff: cot - real, count };
}

function resizeImage(file, maxW = 480) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error('No se pudo leer la imagen'));
    reader.onload = () => {
      const img = new window.Image();
      img.onerror = () => reject(new Error('Imagen inválida'));
      img.onload = () => {
        const scale = Math.min(1, maxW / img.width);
        const w = Math.round(img.width * scale);
        const h = Math.round(img.height * scale);
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL('image/jpeg', 0.72));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}
function downloadDataUrl(filename, dataUrl) {
  const a = document.createElement('a');
  a.href = dataUrl;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}
function downloadText(filename, text) {
  const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  downloadDataUrl(filename, url);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

