function OrderCard({ order, client, onClick }) {
  const saldo = (Number(order.precio) || 0) - (Number(order.abono) || 0);
  const du = daysUntil(order.fechaEntrega);
  const urgent = order.prioridad === 'Alta' && order.etapa !== 'Entregado';
  const late = du < 0 && order.etapa !== 'Entregado';
  const thumb = order.fotos?.[0] || order.foto;
  return (
    <button onClick={onClick} className="w-full text-left rounded-2xl p-3.5 flex gap-3 mb-2.5 active:opacity-80" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
      <div className="w-14 h-14 rounded-xl flex-shrink-0 overflow-hidden flex items-center justify-center" style={{ background: C.cream }}>
        {thumb
          ? <img src={thumb} alt="" className="w-full h-full object-cover" />
          : <ImageOff size={18} style={{ color: C.inkSoft }} />}
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center justify-between gap-2">
          <span className="text-[11px] font-mono tracking-tight" style={{ color: C.inkSoft }}>{order.codigo}</span>
          <PriorityDot p={order.prioridad} />
        </div>
        <p className="font-medium truncate" style={{ color: C.ink }}>{order.prenda || 'Prenda sin nombre'}</p>
        <p className="text-sm truncate" style={{ color: C.inkSoft }}>{client?.nombre || 'Cliente sin nombre'}</p>
        <div className="flex items-center gap-1.5 mt-1.5 flex-wrap">
          <EtapaBadge etapa={order.etapa} />
          {order.tipo === 'Catálogo' && <Badge bg={C.line} fg={C.ink}>De colección</Badge>}
          <Badge bg={C.gold} fg={C.ink}>{pctPagado(order.precio, order.abono)}% pagado</Badge>
          {saldo > 0
            ? <Badge bg={C.line} fg={C.ink}>Saldo {fmtCOP(saldo)}</Badge>
            : <Badge bg="#E4EBE1" fg={C.sage}>Pagado</Badge>}
          {late && <Badge bg={C.brick}>Atrasado</Badge>}
          {!late && urgent && <Badge bg={C.brick}>Urgente</Badge>}
        </div>
      </div>
    </button>
  );
}

