function OrderForm({ initial, clients, lists, orders, catalog, onSave, onCancel, onDelete, onCreateClient }) {
  const [f, setF] = useState(() => {
    if (initial) {
      return { corteResponsable: '', ensambleResponsable: '', tipo: 'Personalizado', coleccionId: '', prendaCatalogoId: '', medioPago: 'Efectivo', ...initial, fotos: (initial.fotos && initial.fotos.length) ? initial.fotos : (initial.foto ? [initial.foto] : []) };
    }
    return {
      codigo: nextCode(orders, 'codigo', 'KAWA'),
      tipo: 'Personalizado', coleccionId: '', prendaCatalogoId: '',
      clientId: '', prenda: '', categoria: lists.categorias[0] || '', talla: lists.tallas[0] || '',
      tela: lists.telas[0] || '', color: lists.colores[0] || '', precio: '', abono: '', medioPago: 'Efectivo',
      fechaEntrega: '', etapa: 'Moldería', prioridad: 'Media', observaciones: '', foto: '',
      fotos: [], metros: '', cierre: 'No', corteResponsable: '', ensambleResponsable: '',
    };
  });
  const [clientMode, setClientMode] = useState(f.clientId ? 'existing' : 'existing');
  const [newClient, setNewClient] = useState({ nombre: '', telefono: '', instagram: '' });
  const [err, setErr] = useState('');
  const fileRef = useRef(null);

  const set = (k, v) => setF(prev => ({ ...prev, [k]: v }));

  async function handleAddPhoto(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const dataUrl = await resizeImage(file);
      setF(prev => ({ ...prev, fotos: [...(prev.fotos || []), dataUrl] }));
    } catch {
      setErr('No se pudo procesar la foto');
    }
    e.target.value = '';
  }
  function removePhoto(idx) {
    setF(prev => ({ ...prev, fotos: prev.fotos.filter((_, i) => i !== idx) }));
  }

  function handleSubmit() {
    if (clientMode === 'existing' && !f.clientId) { setErr('Selecciona un cliente o crea uno nuevo'); return; }
    if (clientMode === 'new' && !newClient.nombre.trim()) { setErr('Escribe el nombre del nuevo cliente'); return; }
    if (f.tipo === 'Catálogo' && !f.prendaCatalogoId) { setErr('Selecciona una prenda del catálogo'); return; }
    if (!f.prenda.trim()) { setErr('Escribe la prenda'); return; }
    if (!f.precio || Number(f.precio) <= 0) { setErr('Escribe un precio válido'); return; }

    let clientId = f.clientId;
    if (clientMode === 'new') {
      const created = onCreateClient(newClient);
      clientId = created.id;
    }
    onSave({ ...f, clientId, precio: Number(f.precio) || 0, abono: Number(f.abono) || 0, metros: Number(f.metros) || 0, foto: f.fotos?.[0] || '' });
  }

  const saldo = (Number(f.precio) || 0) - (Number(f.abono) || 0);
  const fPct = pctPagado(f.precio, f.abono);

  return (
    <div>
      <Field label="Código">
        <TextInput value={f.codigo} disabled />
      </Field>

      <Field label="Tipo de pedido">
        <div className="flex gap-2">
          <button onClick={() => set('tipo', 'Personalizado')} className="flex-1 rounded-xl py-2 text-sm font-medium" style={{ background: f.tipo === 'Personalizado' ? C.wine : C.line, color: f.tipo === 'Personalizado' ? '#fff' : C.ink }}>Personalizado</button>
          <button onClick={() => set('tipo', 'Catálogo')} className="flex-1 rounded-xl py-2 text-sm font-medium" style={{ background: f.tipo === 'Catálogo' ? C.wine : C.line, color: f.tipo === 'Catálogo' ? '#fff' : C.ink }}>De catálogo</button>
        </div>
      </Field>

      {f.tipo === 'Catálogo' && (
        <>
          <Field label="Colección">
            <Select value={f.coleccionId} onChange={e => setF(prev => ({ ...prev, coleccionId: e.target.value, prendaCatalogoId: '' }))}>
              <option value="">Selecciona una colección…</option>
              {catalog.colecciones.map(c => <option key={c.id} value={c.id}>{c.nombre}</option>)}
            </Select>
          </Field>
          {f.coleccionId && (
            <Field label="Prenda">
              <Select value={f.prendaCatalogoId} onChange={e => {
                const col = catalog.colecciones.find(c => c.id === f.coleccionId);
                const p = col?.prendas.find(x => x.id === e.target.value);
                setF(prev => ({ ...prev, prendaCatalogoId: e.target.value, prenda: p?.nombre || prev.prenda, color: p?.color || prev.color, tela: p?.tela || prev.tela, talla: p?.talla || prev.talla, precio: p?.precio || prev.precio, observaciones: p?.detalles || prev.observaciones }));
              }}>
                <option value="">Selecciona una prenda…</option>
                {catalog.colecciones.find(c => c.id === f.coleccionId)?.prendas.map(p => <option key={p.id} value={p.id}>{p.nombre} ({p.disponible || 0} disp.)</option>)}
              </Select>
            </Field>
          )}
        </>
      )}

      <Field label="Cliente" required>
        <div className="flex gap-2 mb-2">
          <button onClick={() => setClientMode('existing')} className="flex-1 rounded-xl py-2 text-sm font-medium" style={{ background: clientMode === 'existing' ? C.wine : C.line, color: clientMode === 'existing' ? '#fff' : C.ink }}>Existente</button>
          <button onClick={() => setClientMode('new')} className="flex-1 rounded-xl py-2 text-sm font-medium" style={{ background: clientMode === 'new' ? C.wine : C.line, color: clientMode === 'new' ? '#fff' : C.ink }}>Nuevo cliente</button>
        </div>
        {clientMode === 'existing' ? (
          <Select value={f.clientId} onChange={e => set('clientId', e.target.value)}>
            <option value="">Selecciona un cliente…</option>
            {clients.map(c => <option key={c.id} value={c.id}>{c.nombre} ({c.codigo})</option>)}
          </Select>
        ) : (
          <div className="space-y-2">
            <TextInput placeholder="Nombre" value={newClient.nombre} onChange={e => setNewClient({ ...newClient, nombre: e.target.value })} />
            <TextInput placeholder="Teléfono (opcional)" value={newClient.telefono} onChange={e => setNewClient({ ...newClient, telefono: e.target.value })} />
            <TextInput placeholder="Instagram (opcional)" value={newClient.instagram} onChange={e => setNewClient({ ...newClient, instagram: e.target.value })} />
          </div>
        )}
      </Field>

      <Field label="Prenda" required>
        <TextInput placeholder="Ej. Vestido Polka Dots" value={f.prenda} onChange={e => set('prenda', e.target.value)} />
      </Field>

      <div className="grid grid-cols-2 gap-3">
        <Field label="Categoría">
          <Select value={f.categoria} onChange={e => set('categoria', e.target.value)}>
            {lists.categorias.map(o => <option key={o}>{o}</option>)}
          </Select>
        </Field>
        <Field label="Talla">
          <Select value={f.talla} onChange={e => set('talla', e.target.value)}>
            {lists.tallas.map(o => <option key={o}>{o}</option>)}
          </Select>
        </Field>
        <Field label="Tela">
          <Select value={f.tela} onChange={e => set('tela', e.target.value)}>
            {lists.telas.map(o => <option key={o}>{o}</option>)}
          </Select>
        </Field>
        <Field label="Color">
          <Select value={f.color} onChange={e => set('color', e.target.value)}>
            {lists.colores.map(o => <option key={o}>{o}</option>)}
          </Select>
        </Field>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <Field label="Metros de tela">
          <TextInput type="number" inputMode="decimal" step="0.1" placeholder="0" value={f.metros} onChange={e => set('metros', e.target.value)} />
        </Field>
        <Field label="Lleva cierre">
          <Select value={f.cierre} onChange={e => set('cierre', e.target.value)}>
            <option>No</option>
            <option>Sí</option>
          </Select>
        </Field>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <Field label="¿Quién corta?">
          <Select value={f.corteResponsable} onChange={e => set('corteResponsable', e.target.value)}>
            <option value="">Sin asignar</option>
            {lists.equipo.map(o => <option key={o}>{o}</option>)}
          </Select>
        </Field>
        <Field label="¿Quién ensambla?">
          <Select value={f.ensambleResponsable} onChange={e => set('ensambleResponsable', e.target.value)}>
            <option value="">Sin asignar</option>
            {lists.equipo.map(o => <option key={o}>{o}</option>)}
          </Select>
        </Field>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <Field label="Precio" required>
          <TextInput type="number" inputMode="numeric" placeholder="0" value={f.precio} onChange={e => set('precio', e.target.value)} />
        </Field>
        <Field label="Abono">
          <TextInput type="number" inputMode="numeric" placeholder="0" value={f.abono} onChange={e => set('abono', e.target.value)} />
        </Field>
      </div>
      <div className="flex gap-2 mb-3">
        {[50, 70, 100].map(pct => (
          <button
            key={pct}
            type="button"
            disabled={!f.precio}
            onClick={() => set('abono', String(Math.round(((Number(f.precio) || 0) * pct) / 100)))}
            className="flex-1 rounded-lg py-1.5 text-xs font-medium disabled:opacity-40"
            style={{ background: C.line, color: C.ink }}
          >
            Abono {pct}%
          </button>
        ))}
      </div>

      <div className="rounded-xl px-3 py-2.5 mb-3" style={{ background: C.line }}>
        <div className="flex items-center justify-between text-sm mb-1.5">
          <span style={{ color: C.inkSoft }}>Saldo</span>
          <span className="font-semibold" style={{ color: C.ink }}>{fmtCOP(saldo)}</span>
        </div>
        <div className="h-1.5 rounded-full overflow-hidden mb-1" style={{ background: '#fff' }}>
          <div className="h-full rounded-full" style={{ width: `${fPct}%`, background: C.wine }} />
        </div>
        <p className="text-xs text-right font-medium" style={{ color: C.wine }}>{fPct}% pagado</p>
      </div>

      <Field label="Medio de pago del abono">
        <Select value={f.medioPago} onChange={e => set('medioPago', e.target.value)}>
          {(lists.cuentas || ['Efectivo']).map(o => <option key={o}>{o}</option>)}
        </Select>
      </Field>

      <div className="grid grid-cols-2 gap-3">
        <Field label="Fecha de entrega">
          <TextInput type="date" value={f.fechaEntrega} onChange={e => set('fechaEntrega', e.target.value)} />
        </Field>
        <Field label="Prioridad">
          <Select value={f.prioridad} onChange={e => set('prioridad', e.target.value)}>
            {PRIORIDADES.map(p => <option key={p.key}>{p.key}</option>)}
          </Select>
        </Field>
      </div>

      <Field label="Etapa">
        <Select value={f.etapa} onChange={e => set('etapa', e.target.value)}>
          {ETAPA_KEYS.map(o => <option key={o}>{o}</option>)}
        </Select>
      </Field>

      <Field label="Observaciones">
        <TextArea placeholder="Detalles, medidas, pedidos especiales…" value={f.observaciones} onChange={e => set('observaciones', e.target.value)} />
      </Field>

      <Field label="Fotos o referencias">
        <input ref={fileRef} type="file" accept="image/*" onChange={handleAddPhoto} className="hidden" />
        <div className="flex flex-wrap gap-2 mb-2">
          {(f.fotos || []).map((foto, i) => (
            <div key={i} className="relative w-16 h-16 rounded-lg overflow-hidden flex-shrink-0" style={{ border: `1px solid ${C.line}` }}>
              <img src={foto} className="w-full h-full object-cover" />
              <button onClick={() => removePhoto(i)} className="absolute top-0.5 right-0.5 w-5 h-5 rounded-full flex items-center justify-center" style={{ background: 'rgba(0,0,0,0.6)' }}>
                <X size={11} color="#fff" />
              </button>
            </div>
          ))}
        </div>
        <button onClick={() => fileRef.current?.click()} className="w-full rounded-xl py-3 flex items-center justify-center gap-2 border" style={{ borderColor: C.line, borderStyle: 'dashed' }}>
          <Camera size={18} style={{ color: C.inkSoft }} />
          <span className="text-sm" style={{ color: C.inkSoft }}>Agregar foto</span>
        </button>
      </Field>

      {err && <p className="text-sm mb-2" style={{ color: C.brick }}>{err}</p>}

      <div className="flex gap-2 mt-4">
        {initial && (
          <button onClick={() => onDelete(initial)} className="rounded-xl py-2.5 px-4" style={{ color: C.brick }}>
            <Trash2 size={18} />
          </button>
        )}
        <GhostButton full onClick={onCancel}>Cancelar</GhostButton>
        <PrimaryButton full onClick={handleSubmit}>Guardar</PrimaryButton>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Order Detail (view + move stage)                                   */
/* ------------------------------------------------------------------ */
function OrderDetail({ order, client, onEdit, onClose, onStageChange, onOpenCosts }) {
  const idx = ETAPA_KEYS.indexOf(order.etapa);
  const saldo = (Number(order.precio) || 0) - (Number(order.abono) || 0);
  const pct = pctPagado(order.precio, order.abono);
  const fotos = (order.fotos && order.fotos.length) ? order.fotos : (order.foto ? [order.foto] : []);

  function handleDownloadOrder() {
    const lines = [
      `Pedido ${order.codigo}`,
      `Cliente: ${client?.nombre || ''} (${client?.codigo || ''})`,
      `Prenda: ${order.prenda || ''}`,
      `Categoría: ${order.categoria || ''}`,
      `Talla: ${order.talla || ''}`,
      `Tela: ${order.tela || ''}`,
      `Color: ${order.color || ''}`,
      `Metros de tela: ${order.metros || 0}`,
      `Lleva cierre: ${order.cierre || 'No'}`,
      `¿Quién corta?: ${order.corteResponsable || 'Sin asignar'}`,
      `¿Quién ensambla?: ${order.ensambleResponsable || 'Sin asignar'}`,
      `Precio: ${fmtCOP(order.precio)}`,
      `Abono: ${fmtCOP(order.abono)}`,
      `Saldo: ${fmtCOP(saldo)}`,
      `% pagado: ${pct}%`,
      `Fecha de entrega: ${fmtDate(order.fechaEntrega)}`,
      `Etapa: ${order.etapa}`,
      `Prioridad: ${order.prioridad}`,
      `Observaciones: ${order.observaciones || ''}`,
    ];
    downloadText(`Pedido_${order.codigo}.txt`, lines.join('\n'));
  }

  return (
    <div>
      {fotos.length > 0 && (
        <div className="flex gap-2 mb-4 overflow-x-auto">
          {fotos.map((foto, i) => (
            <div key={i} className="relative w-28 h-28 rounded-2xl overflow-hidden flex-shrink-0" style={{ border: `1px solid ${C.line}` }}>
              <img src={foto} className="w-full h-full object-cover" />
              <button onClick={() => downloadDataUrl(`${order.codigo}_foto${i + 1}.jpg`, foto)} className="absolute bottom-1 right-1 w-7 h-7 rounded-full flex items-center justify-center" style={{ background: 'rgba(0,0,0,0.55)' }}>
                <Download size={13} color="#fff" />
              </button>
            </div>
          ))}
        </div>
      )}
      <div className="flex items-center justify-between mb-1">
        <span className="text-[11px] font-mono" style={{ color: C.inkSoft }}>{order.codigo}</span>
        <PriorityDot p={order.prioridad} />
      </div>
      <h3 className="text-2xl font-semibold mb-1" style={{ color: C.ink, fontFamily: 'Georgia, serif' }}>{order.prenda}</h3>
      <p className="text-sm mb-3" style={{ color: C.inkSoft }}>{client?.nombre} · {client?.codigo}</p>

      <div className="grid grid-cols-2 gap-2 mb-4">
        <InfoChip label="Categoría" value={order.categoria} />
        <InfoChip label="Talla" value={order.talla} />
        <InfoChip label="Tela" value={order.tela} />
        <InfoChip label="Color" value={order.color} />
        <InfoChip label="Metros de tela" value={order.metros ? `${order.metros} m` : '—'} />
        <InfoChip label="Cierre" value={order.cierre || 'No'} />
        <InfoChip label="Quién corta" value={order.corteResponsable || 'Sin asignar'} />
        <InfoChip label="Quién ensambla" value={order.ensambleResponsable || 'Sin asignar'} />
        <InfoChip label="Medio de pago" value={order.medioPago || 'Efectivo'} />
        <InfoChip label="Entrega" value={fmtDate(order.fechaEntrega)} />
        <InfoChip label="Prioridad" value={order.prioridad} />
      </div>

      <div className="rounded-xl p-3 mb-4" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
        <div className="flex justify-between text-sm mb-1"><span style={{ color: C.inkSoft }}>Precio</span><span style={{ color: C.ink }}>{fmtCOP(order.precio)}</span></div>
        <div className="flex justify-between text-sm mb-1"><span style={{ color: C.inkSoft }}>Abono</span><span style={{ color: C.ink }}>{fmtCOP(order.abono)}</span></div>
        <div className="flex justify-between text-sm font-semibold mb-2"><span style={{ color: C.ink }}>Saldo</span><span style={{ color: saldo > 0 ? C.brick : C.sage }}>{fmtCOP(saldo)}</span></div>
        <div className="h-1.5 rounded-full overflow-hidden mb-1" style={{ background: C.line }}>
          <div className="h-full rounded-full" style={{ width: `${pct}%`, background: C.wine }} />
        </div>
        <p className="text-xs text-right font-medium" style={{ color: C.wine }}>{pct}% pagado</p>
      </div>

      {order.observaciones && (
        <div className="mb-4">
          <p className="text-[11px] uppercase tracking-wider mb-1" style={{ color: C.inkSoft }}>Observaciones</p>
          <p className="text-sm" style={{ color: C.ink }}>{order.observaciones}</p>
        </div>
      )}

      <p className="text-[11px] uppercase tracking-wider mb-2" style={{ color: C.inkSoft }}>Etapa de producción — toca para trasladar</p>
      <div className="flex gap-2 overflow-x-auto pb-1 mb-2">
        {ETAPAS.map(et => {
          const active = et.key === order.etapa;
          const dark = ['Ensamble', 'Detalles', 'Planchado', 'Calidad', 'Empaque'].includes(et.key);
          return (
            <button
              key={et.key}
              onClick={() => onStageChange(et.key)}
              className="flex-shrink-0 rounded-full px-3 py-1.5 text-xs font-medium"
              style={{ background: active ? et.color : C.line, color: active ? (dark ? '#fff' : C.ink) : C.inkSoft, border: active ? `1px solid ${et.color}` : `1px solid ${C.line}` }}
            >
              {et.key}
            </button>
          );
        })}
      </div>

      <div className="flex gap-2 mt-5">
        <GhostButton full onClick={onClose}>Cerrar</GhostButton>
        <PrimaryButton full onClick={onEdit}>Editar</PrimaryButton>
      </div>
      <button onClick={handleDownloadOrder} className="w-full rounded-xl py-2.5 mt-2 text-sm font-medium flex items-center justify-center gap-2" style={{ background: C.line, color: C.ink }}>
        <Download size={15} /> Descargar pedido
      </button>
      {order.costos && (
        <button onClick={onOpenCosts} className="w-full rounded-xl py-2.5 mt-2 text-sm font-medium flex items-center justify-center gap-2" style={{ background: C.gold, color: C.ink }}>
          <Calculator size={15} /> Costos reales de este pedido
        </button>
      )}
    </div>
  );
}
function InfoChip({ label, value }) {
  return (
    <div className="rounded-xl px-3 py-2" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
      <p className="text-[10px] uppercase tracking-wider" style={{ color: C.inkSoft }}>{label}</p>
      <p className="text-sm font-medium truncate" style={{ color: C.ink }}>{value || '—'}</p>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Inicio                                                              */
/* ------------------------------------------------------------------ */
function Inicio({ orders, clients, catalog, goals, onOpenOrder, goTab }) {
  const activos = orders.filter(o => o.etapa !== 'Entregado');
  const urgentes = activos.filter(o => o.prioridad === 'Alta');
  const proximas = activos.filter(o => o.fechaEntrega && daysUntil(o.fechaEntrega) <= 7).sort((a, b) => daysUntil(a.fechaEntrega) - daysUntil(b.fechaEntrega));
  const pendiente = orders.reduce((s, o) => s + Math.max(0, (Number(o.precio) || 0) - (Number(o.abono) || 0)), 0);
  const porEtapa = ETAPA_KEYS.map(k => ({ k, n: orders.filter(o => o.etapa === k).length }));
  const maxPorEtapa = Math.max(1, ...porEtapa.map(e => e.n));
  const disponible = (catalog?.colecciones || []).reduce((s, c) => s + c.prendas.reduce((s2, p) => s2 + (Number(p.disponible) || 0), 0), 0);
  const hoy = new Date().toISOString().slice(0, 10);
  const metasVigentes = (goals || []).filter(g => !g.fechaFin || g.fechaFin >= hoy).map(g => ({ ...g, progreso: computeGoalProgress(g, orders) }));
  const cumplidas = metasVigentes.filter(m => m.progreso.cumplida).length;
  const noCumplidas = metasVigentes.length - cumplidas;

  return (
    <div className="pb-4">
      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-3 mb-4">
        <StatCard label="Pedidos activos" value={activos.length} onClick={() => goTab('pedidos')} />
        <StatCard label="Urgentes" value={urgentes.length} accent={C.brick} onClick={() => goTab('pedidos')} />
        <StatCard label="Entregas ≤ 7 días" value={proximas.length} onClick={() => goTab('mas', 'calendario')} />
        <StatCard label="Dinero pendiente" value={fmtCOP(pendiente)} small onClick={() => goTab('mas', 'pagos')} />
        <StatCard label="Prendas disponibles" value={disponible} onClick={() => goTab('mas', 'inventario')} />
        <StatCard label="Metas activas" value={metasVigentes.length} onClick={() => goTab('mas', 'metas')} />
      </div>

      {metasVigentes.length > 0 && (
        <>
          <SectionTitle>Cumplimiento de metas</SectionTitle>
          <div className="grid grid-cols-2 gap-3 mb-3">
            <StatCard label="Cumplidas" value={cumplidas} accent={C.sage} onClick={() => goTab('mas', 'metas')} />
            <StatCard label="No cumplidas" value={noCumplidas} accent={C.brick} onClick={() => goTab('mas', 'metas')} />
          </div>
          <div className="rounded-2xl p-4 mb-5" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
            {metasVigentes.map(m => (
              <div key={m.id} className="mb-2.5 last:mb-0">
                <div className="flex items-center justify-between mb-1">
                  <span className="text-xs truncate" style={{ color: C.inkSoft }}>{m.nombre}</span>
                  <span className="text-xs flex-shrink-0" style={{ color: m.progreso.cumplida ? C.sage : C.inkSoft }}>{m.progreso.pct}%</span>
                </div>
                <div className="h-2 rounded-full overflow-hidden" style={{ background: C.line }}>
                  <div className="h-full rounded-full" style={{ width: `${m.progreso.pct}%`, background: m.progreso.cumplida ? C.sage : C.wine }} />
                </div>
              </div>
            ))}
          </div>
        </>
      )}

      <SectionTitle>Pedidos por etapa</SectionTitle>
      <div className="rounded-2xl p-4 mb-5" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
        {porEtapa.map(e => (
          <div key={e.k} className="flex items-center gap-2 mb-2 last:mb-0">
            <span className="text-xs w-20 flex-shrink-0 truncate" style={{ color: C.inkSoft }}>{e.k}</span>
            <div className="flex-1 h-2 rounded-full overflow-hidden" style={{ background: C.line }}>
              <div className="h-full rounded-full" style={{ width: `${(e.n / maxPorEtapa) * 100}%`, background: ETAPAS.find(x => x.key === e.k).color }} />
            </div>
            <span className="text-xs w-4 text-right" style={{ color: C.ink }}>{e.n}</span>
          </div>
        ))}
      </div>

      <SectionTitle>Entregas próximas</SectionTitle>
      {proximas.length === 0
        ? <p className="text-sm px-1" style={{ color: C.inkSoft }}>No hay entregas en los próximos 7 días.</p>
        : proximas.slice(0, 5).map(o => <OrderCard key={o.id} order={o} client={clients.find(c => c.id === o.clientId)} onClick={() => onOpenOrder(o)} />)}
    </div>
  );
}
function StatCard({ label, value, accent, small, onClick }) {
  return (
    <button onClick={onClick} className="rounded-2xl p-4 text-left active:opacity-80" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
      <p className="text-[11px] uppercase tracking-wider mb-1" style={{ color: C.inkSoft }}>{label}</p>
      <p className={small ? 'text-lg font-semibold' : 'text-2xl font-semibold'} style={{ color: accent || C.ink, fontFamily: 'Georgia, serif' }}>{value}</p>
    </button>
  );
}
function SectionTitle({ children }) {
  return <h3 className="text-[15px] font-semibold uppercase tracking-wider mb-2 px-1" style={{ color: C.inkSoft }}>{children}</h3>;
}

/* ------------------------------------------------------------------ */
/*  Pedidos                                                             */
/* ------------------------------------------------------------------ */
function Pedidos({ orders, clients, onOpenOrder, onNew }) {
  const [q, setQ] = useState('');
  const [etapaFilter, setEtapaFilter] = useState('Todas');
  const [showFilters, setShowFilters] = useState(false);

  const filtered = useMemo(() => {
    return orders.filter(o => {
      if (etapaFilter !== 'Todas' && o.etapa !== etapaFilter) return false;
      if (q) {
        const client = clients.find(c => c.id === o.clientId);
        const hay = `${o.codigo} ${o.prenda} ${client?.nombre || ''}`.toLowerCase();
        if (!hay.includes(q.toLowerCase())) return false;
      }
      return true;
    }).sort((a, b) => (a.fechaEntrega || '9999').localeCompare(b.fechaEntrega || '9999'));
  }, [orders, clients, q, etapaFilter]);

  return (
    <div className="pb-24">
      <div className="flex gap-2 mb-3">
        <div className="flex-1 flex items-center gap-2 rounded-xl px-3" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
          <Search size={16} style={{ color: C.inkSoft }} />
          <input value={q} onChange={e => setQ(e.target.value)} placeholder="Buscar código, prenda o cliente…" className="flex-1 py-2.5 bg-transparent outline-none text-[15px]" style={{ color: C.ink }} />
        </div>
        <button onClick={() => setShowFilters(s => !s)} className="w-11 h-11 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: showFilters ? C.wine : C.paper, border: `1px solid ${C.line}` }}>
          <Filter size={16} style={{ color: showFilters ? '#fff' : C.ink }} />
        </button>
      </div>
      {showFilters && (
        <div className="flex gap-2 mb-3 overflow-x-auto pb-1">
          {['Todas', ...ETAPA_KEYS].map(e => (
            <button key={e} onClick={() => setEtapaFilter(e)} className="flex-shrink-0 rounded-full px-3 py-1.5 text-xs font-medium" style={{ background: etapaFilter === e ? C.wine : C.line, color: etapaFilter === e ? '#fff' : C.ink }}>
              {e}
            </button>
          ))}
        </div>
      )}
      {filtered.length === 0
        ? <EmptyState icon={ClipboardList} title="Sin pedidos" subtitle="Crea tu primer pedido con el botón +" />
        : filtered.map(o => <OrderCard key={o.id} order={o} client={clients.find(c => c.id === o.clientId)} onClick={() => onOpenOrder(o)} />)}
      <FloatingAdd onClick={onNew} />
    </div>
  );
}
function FloatingAdd({ onClick }) {
  return (
    <button onClick={onClick} className="fixed bottom-24 right-5 w-14 h-14 rounded-full flex items-center justify-center shadow-lg z-30" style={{ background: C.wine }}>
      <Plus size={24} color="#fff" />
    </button>
  );
}

/* ------------------------------------------------------------------ */
/*  Producción (kanban)                                                 */
/* ------------------------------------------------------------------ */
function Produccion({ orders, clients, onOpenOrder }) {
  const active = orders.filter(o => o.etapa !== 'Entregado');
  return (
    <div className="pb-4 grid md:grid-cols-2 xl:grid-cols-3 gap-4">
      {ETAPAS.filter(et => et.key !== 'Entregado').map(et => {
        const items = active.filter(o => o.etapa === et.key).sort((a, b) => (a.fechaEntrega || '9999').localeCompare(b.fechaEntrega || '9999'));
        return (
          <div key={et.key}>
            <div className="flex items-center gap-2 mb-2 px-1">
              <span className="w-2.5 h-2.5 rounded-full" style={{ background: et.color }} />
              <span className="text-sm font-semibold" style={{ color: C.ink }}>{et.key}</span>
              <span className="text-xs ml-auto" style={{ color: C.inkSoft }}>{items.length}</span>
            </div>
            <div className="rounded-2xl p-2" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
              {items.length === 0
                ? <p className="text-xs text-center py-4" style={{ color: C.inkSoft }}>Vacío</p>
                : items.map(o => (
                  <button key={o.id} onClick={() => onOpenOrder(o)} className="w-full text-left rounded-xl p-2.5 mb-2 last:mb-0 active:opacity-80 flex items-center gap-3" style={{ background: C.cream }}>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between gap-2">
                        <span className="text-[10px] font-mono" style={{ color: C.inkSoft }}>{o.codigo}</span>
                        <PriorityDot p={o.prioridad} />
                      </div>
                      <p className="text-sm font-medium truncate" style={{ color: C.ink }}>{o.prenda}</p>
                      <p className="text-xs truncate" style={{ color: C.inkSoft }}>{clients.find(c => c.id === o.clientId)?.nombre}</p>
                    </div>
                    {o.fechaEntrega && <p className="text-[11px] flex-shrink-0" style={{ color: C.inkSoft }}>{fmtDate(o.fechaEntrega)}</p>}
                  </button>
                ))}
            </div>
          </div>
        );
      })}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Clientes                                                            */
/* ------------------------------------------------------------------ */
function Clientes({ clients, orders, onSelect, onNew }) {
  const [q, setQ] = useState('');
  const filtered = clients.filter(c => `${c.nombre} ${c.codigo}`.toLowerCase().includes(q.toLowerCase()));
  return (
    <div className="pb-24">
      <div className="flex items-center gap-2 rounded-xl px-3 mb-3" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
        <Search size={16} style={{ color: C.inkSoft }} />
        <input value={q} onChange={e => setQ(e.target.value)} placeholder="Buscar cliente…" className="flex-1 py-2.5 bg-transparent outline-none text-[15px]" style={{ color: C.ink }} />
      </div>
      {filtered.length === 0
        ? <EmptyState icon={Users} title="Sin clientas" subtitle="Agrega una clienta con el botón +" />
        : filtered.map(c => {
          const pedidos = orders.filter(o => o.clientId === c.id);
          const total = pedidos.reduce((s, o) => s + (Number(o.precio) || 0), 0);
          return (
            <button key={c.id} onClick={() => onSelect(c)} className="w-full text-left rounded-2xl p-3.5 flex items-center gap-3 mb-2.5 active:opacity-80" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
              <div className="w-11 h-11 rounded-full flex items-center justify-center flex-shrink-0 font-semibold" style={{ background: C.line, color: C.wine }}>
                {(c.nombre || '?')[0]?.toUpperCase()}
              </div>
              <div className="flex-1 min-w-0">
                <p className="font-medium truncate" style={{ color: C.ink }}>{c.nombre}</p>
                <p className="text-xs" style={{ color: C.inkSoft }}>{c.codigo} · {pedidos.length} pedido{pedidos.length !== 1 ? 's' : ''}</p>
              </div>
              <p className="text-sm font-semibold flex-shrink-0" style={{ color: C.ink }}>{fmtCOP(total)}</p>
            </button>
          );
        })}
      <FloatingAdd onClick={onNew} />
    </div>
  );
}

function ClientForm({ initial, onSave, onCancel, onDelete }) {
  const [f, setF] = useState(initial ? { correo: '', fechaNacimiento: '', ...initial } : { nombre: '', telefono: '', instagram: '', correo: '', fechaNacimiento: '' });
  const [err, setErr] = useState('');
  return (
    <div>
      <Field label="Nombre" required><TextInput value={f.nombre} onChange={e => setF({ ...f, nombre: e.target.value })} /></Field>
      <Field label="Teléfono"><TextInput value={f.telefono} onChange={e => setF({ ...f, telefono: e.target.value })} /></Field>
      <Field label="Instagram"><TextInput value={f.instagram} onChange={e => setF({ ...f, instagram: e.target.value })} placeholder="@usuario" /></Field>
      <Field label="Correo electrónico"><TextInput type="email" value={f.correo} onChange={e => setF({ ...f, correo: e.target.value })} placeholder="correo@ejemplo.com" /></Field>
      <Field label="Fecha de nacimiento"><TextInput type="date" value={f.fechaNacimiento} onChange={e => setF({ ...f, fechaNacimiento: e.target.value })} /></Field>
      {err && <p className="text-sm mb-2" style={{ color: C.brick }}>{err}</p>}
      <div className="flex gap-2 mt-4">
        {initial && <button onClick={() => onDelete(initial)} className="rounded-xl py-2.5 px-4" style={{ color: C.brick }}><Trash2 size={18} /></button>}
        <GhostButton full onClick={onCancel}>Cancelar</GhostButton>
        <PrimaryButton full onClick={() => f.nombre.trim() ? onSave(f) : setErr('Escribe el nombre')}>Guardar</PrimaryButton>
      </div>
    </div>
  );
}

function ClientDetail({ client, orders, quotes, onEdit, onClose, onOpenOrder }) {
  const pedidos = orders.filter(o => o.clientId === client.id).sort((a, b) => (b.fechaEntrega || '').localeCompare(a.fechaEntrega || ''));
  const total = pedidos.reduce((s, o) => s + (Number(o.precio) || 0), 0);
  const misCotizaciones = (quotes || []).filter(q => q.clientId === client.id);
  const medidasLlenas = client.medidas ? MEDIDA_FIELDS.filter(f => client.medidas[f.key]) : [];
  const extrasLlenas = client.medidas?.extras?.filter(e => e.nombre && e.valor) || [];
  return (
    <div>
      <div className="flex items-center gap-3 mb-4">
        <div className="w-14 h-14 rounded-full flex items-center justify-center font-semibold text-xl" style={{ background: C.line, color: C.wine }}>
          {(client.nombre || '?')[0]?.toUpperCase()}
        </div>
        <div>
          <h3 className="text-xl font-semibold" style={{ color: C.ink, fontFamily: 'Georgia, serif' }}>{client.nombre}</h3>
          <p className="text-xs" style={{ color: C.inkSoft }}>{client.codigo}</p>
        </div>
      </div>
      <div className="grid grid-cols-2 gap-2 mb-4">
        {client.telefono && <InfoChip label="Teléfono" value={client.telefono} />}
        {client.instagram && <InfoChip label="Instagram" value={client.instagram} />}
        {client.correo && <InfoChip label="Correo" value={client.correo} />}
        {client.fechaNacimiento && <InfoChip label="Cumpleaños" value={fmtDate(client.fechaNacimiento)} />}
        <InfoChip label="Compras realizadas" value={pedidos.length} />
        <InfoChip label="Total comprado" value={fmtCOP(total)} />
        <InfoChip label="Cotizaciones" value={misCotizaciones.length} />
      </div>

      {(medidasLlenas.length > 0 || extrasLlenas.length > 0) && (
        <>
          <SectionTitle>Medidas guardadas</SectionTitle>
          <div className="grid grid-cols-2 gap-2 mb-4">
            {medidasLlenas.map(f => <InfoChip key={f.key} label={f.label} value={`${client.medidas[f.key]} cm`} />)}
            {extrasLlenas.map(e => <InfoChip key={e.id} label={e.nombre} value={`${e.valor} cm`} />)}
          </div>
        </>
      )}

      <SectionTitle>Historial de pedidos</SectionTitle>
      {pedidos.length === 0
        ? <p className="text-sm px-1 mb-3" style={{ color: C.inkSoft }}>Aún no tiene pedidos.</p>
        : pedidos.map(o => <OrderCard key={o.id} order={o} client={client} onClick={() => onOpenOrder(o)} />)}
      <div className="flex gap-2 mt-4">
        <GhostButton full onClick={onClose}>Cerrar</GhostButton>
        <PrimaryButton full onClick={onEdit}>Editar</PrimaryButton>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Pagos                                                               */
/* ------------------------------------------------------------------ */
function Pagos({ orders, clients, onOpenOrder, goals }) {
  const totalVendido = orders.reduce((s, o) => s + (Number(o.precio) || 0), 0);
  const totalRecibido = orders.reduce((s, o) => s + (Number(o.abono) || 0), 0);
  const totalPendiente = totalVendido - totalRecibido;
  const al50 = orders.filter(o => paymentStatus(o.precio, o.abono) === 'Parcial');
  const al100 = orders.filter(o => paymentStatus(o.precio, o.abono) === 'Pagado');
  const pendientes = orders.filter(o => (Number(o.precio) || 0) - (Number(o.abono) || 0) > 0).sort((a, b) => ((Number(b.precio) || 0) - (Number(b.abono) || 0)) - ((Number(a.precio) || 0) - (Number(a.abono) || 0)));
  const hoy = new Date().toISOString().slice(0, 10);
  const metasIngresos = (goals || []).filter(g => g.tipo === 'ingresos' && (!g.fechaFin || g.fechaFin >= hoy));

  return (
    <div className="pb-6">
      <div className="grid grid-cols-2 gap-3 mb-3">
        <StatCard label="Total vendido" value={fmtCOP(totalVendido)} small />
        <StatCard label="Total recibido" value={fmtCOP(totalRecibido)} small accent={C.sage} />
        <StatCard label="Total pendiente" value={fmtCOP(totalPendiente)} small accent={C.brick} />
        <StatCard label="Pagados 100%" value={al100.length} />
      </div>
      <StatCard label="Con abono parcial" value={al50.length} />

      {metasIngresos.length > 0 && (
        <>
          <SectionTitle>Metas de ingresos</SectionTitle>
          <div className="rounded-2xl p-4 mb-5" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
            {metasIngresos.map(g => {
              const p = computeGoalProgress(g, orders);
              return (
                <div key={g.id} className="mb-3 last:mb-0">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-sm font-medium" style={{ color: C.ink }}>{g.nombre}</span>
                    <span className="text-xs" style={{ color: p.cumplida ? C.sage : C.inkSoft }}>{p.pct}%</span>
                  </div>
                  <div className="h-3 rounded-full overflow-hidden mb-1" style={{ background: C.line }}>
                    <div className="h-full rounded-full" style={{ width: `${p.pct}%`, background: p.cumplida ? C.sage : C.wine }} />
                  </div>
                  <p className="text-xs" style={{ color: C.inkSoft }}>{fmtCOP(p.actual)} de {fmtCOP(p.objetivo)}</p>
                </div>
              );
            })}
          </div>
        </>
      )}

      <SectionTitle>Saldos pendientes</SectionTitle>
      {pendientes.length === 0
        ? <p className="text-sm px-1" style={{ color: C.inkSoft }}>No hay saldos pendientes 🎉</p>
        : pendientes.map(o => <OrderCard key={o.id} order={o} client={clients.find(c => c.id === o.clientId)} onClick={() => onOpenOrder(o)} />)}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Calendario                                                          */
/* ------------------------------------------------------------------ */
function Calendario({ orders, clients, onOpenOrder }) {
  const [cursor, setCursor] = useState(() => { const d = new Date(); d.setDate(1); return d; });
  const [selected, setSelected] = useState(null);

  const year = cursor.getFullYear(), month = cursor.getMonth();
  const firstDow = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells = [];
  for (let i = 0; i < firstDow; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  const byDate = {};
  orders.forEach(o => { if (o.fechaEntrega) { byDate[o.fechaEntrega] = (byDate[o.fechaEntrega] || []).concat(o); } });
  const isoFor = d => `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  const selectedOrders = selected ? (byDate[selected] || []) : [];

  return (
    <div className="pb-6">
      <div className="flex items-center justify-between mb-3">
        <button onClick={() => setCursor(new Date(year, month - 1, 1))} className="w-9 h-9 rounded-full flex items-center justify-center" style={{ background: C.paper, border: `1px solid ${C.line}` }}><ChevronLeft size={16} /></button>
        <p className="font-semibold capitalize" style={{ color: C.ink, fontFamily: 'Georgia, serif' }}>{cursor.toLocaleDateString('es-CO', { month: 'long', year: 'numeric' })}</p>
        <button onClick={() => setCursor(new Date(year, month + 1, 1))} className="w-9 h-9 rounded-full flex items-center justify-center" style={{ background: C.paper, border: `1px solid ${C.line}` }}><ChevronRight size={16} /></button>
      </div>
      <div className="grid grid-cols-7 gap-1 mb-1">
        {['D', 'L', 'M', 'X', 'J', 'V', 'S'].map(d => <p key={d} className="text-center text-[11px] font-medium" style={{ color: C.inkSoft }}>{d}</p>)}
      </div>
      <div className="grid grid-cols-7 gap-1 mb-4">
        {cells.map((d, i) => {
          if (!d) return <div key={i} />;
          const iso = isoFor(d);
          const has = byDate[iso]?.length;
          const isSel = selected === iso;
          return (
            <button key={i} onClick={() => setSelected(iso)} className="aspect-square rounded-xl flex flex-col items-center justify-center relative" style={{ background: isSel ? C.wine : has ? C.line : 'transparent' }}>
              <span className="text-sm" style={{ color: isSel ? '#fff' : C.ink }}>{d}</span>
              {has ? <span className="w-1.5 h-1.5 rounded-full absolute bottom-1.5" style={{ background: isSel ? '#fff' : C.wine }} /> : null}
            </button>
          );
        })}
      </div>
      <SectionTitle>{selected ? `Entregas · ${fmtDate(selected)}` : 'Selecciona un día'}</SectionTitle>
      {selected && selectedOrders.length === 0 && <p className="text-sm px-1" style={{ color: C.inkSoft }}>Sin entregas ese día.</p>}
      {selectedOrders.map(o => <OrderCard key={o.id} order={o} client={clients.find(c => c.id === o.clientId)} onClick={() => onOpenOrder(o)} />)}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Listas y desplegables                                               */
/* ------------------------------------------------------------------ */
function Listas({ lists, onChange, onChangePassword, onChangePasswordAvanzada }) {
  const [draft, setDraft] = useState({ categorias: '', tallas: '', telas: '', colores: '', asesores: '', equipo: '', cuentas: '' });
  const [customName, setCustomName] = useState('');
  const [customDraft, setCustomDraft] = useState({});
  const labels = { categorias: 'Categorías', tallas: 'Tallas', telas: 'Telas', colores: 'Colores', asesores: 'Asesores (cotizaciones)', equipo: 'Equipo (corte y ensamble)', cuentas: 'Métodos de pago' };
  const custom = lists.custom || [];

  function add(key) {
    const v = draft[key].trim();
    if (!v || lists[key].includes(v)) return;
    onChange({ ...lists, [key]: [...lists[key], v] });
    setDraft({ ...draft, [key]: '' });
  }
  function remove(key, v) {
    onChange({ ...lists, [key]: lists[key].filter(x => x !== v) });
  }
  function addCustomList() {
    const nombre = customName.trim();
    if (!nombre) return;
    onChange({ ...lists, custom: [...custom, { id: uid(), nombre, items: [] }] });
    setCustomName('');
  }
  function removeCustomList(id) {
    onChange({ ...lists, custom: custom.filter(c => c.id !== id) });
  }
  function addCustomItem(id) {
    const v = (customDraft[id] || '').trim();
    if (!v) return;
    onChange({ ...lists, custom: custom.map(c => c.id === id ? { ...c, items: c.items.includes(v) ? c.items : [...c.items, v] } : c) });
    setCustomDraft({ ...customDraft, [id]: '' });
  }
  function removeCustomItem(id, v) {
    onChange({ ...lists, custom: custom.map(c => c.id === id ? { ...c, items: c.items.filter(x => x !== v) } : c) });
  }

  return (
    <div className="pb-6">
      {Object.keys(labels).map(key => (
        <div key={key} className="mb-5">
          <SectionTitle>{labels[key]}</SectionTitle>
          <div className="flex flex-wrap gap-2 mb-2">
            {lists[key].map(v => (
              <span key={v} className="inline-flex items-center gap-1.5 rounded-full pl-3 pr-1.5 py-1 text-sm" style={{ background: C.paper, border: `1px solid ${C.line}`, color: C.ink }}>
                {v}
                <button onClick={() => remove(key, v)} className="w-5 h-5 rounded-full flex items-center justify-center" style={{ background: C.line }}><X size={11} /></button>
              </span>
            ))}
          </div>
          <div className="flex gap-2">
            <TextInput placeholder={`Nueva opción de ${labels[key].toLowerCase()}`} value={draft[key]} onChange={e => setDraft({ ...draft, [key]: e.target.value })} onKeyDown={e => e.key === 'Enter' && add(key)} />
            <button onClick={() => add(key)} className="w-11 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: C.wine }}><Plus size={18} color="#fff" /></button>
          </div>
        </div>
      ))}

      {custom.map(c => (
        <div key={c.id} className="mb-5">
          <div className="flex items-center justify-between mb-2">
            <SectionTitle>{c.nombre}</SectionTitle>
            <button onClick={() => removeCustomList(c.id)} className="text-xs flex-shrink-0" style={{ color: C.brick }}>Eliminar lista</button>
          </div>
          <div className="flex flex-wrap gap-2 mb-2">
            {c.items.map(v => (
              <span key={v} className="inline-flex items-center gap-1.5 rounded-full pl-3 pr-1.5 py-1 text-sm" style={{ background: C.paper, border: `1px solid ${C.line}`, color: C.ink }}>
                {v}
                <button onClick={() => removeCustomItem(c.id, v)} className="w-5 h-5 rounded-full flex items-center justify-center" style={{ background: C.line }}><X size={11} /></button>
              </span>
            ))}
          </div>
          <div className="flex gap-2">
            <TextInput placeholder={`Nueva opción de ${c.nombre.toLowerCase()}`} value={customDraft[c.id] || ''} onChange={e => setCustomDraft({ ...customDraft, [c.id]: e.target.value })} onKeyDown={e => e.key === 'Enter' && addCustomItem(c.id)} />
            <button onClick={() => addCustomItem(c.id)} className="w-11 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: C.wine }}><Plus size={18} color="#fff" /></button>
          </div>
        </div>
      ))}

      <div className="mb-5">
        <SectionTitle>Agregar otra lista</SectionTitle>
        <p className="text-xs mb-2" style={{ color: C.inkSoft }}>Crea cualquier lista nueva que quieras usar más adelante en tus pedidos o prendas.</p>
        <div className="flex gap-2">
          <TextInput placeholder="Ej. Tipos de acabado" value={customName} onChange={e => setCustomName(e.target.value)} onKeyDown={e => e.key === 'Enter' && addCustomList()} />
          <button onClick={addCustomList} className="w-11 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: C.wine }}><Plus size={18} color="#fff" /></button>
        </div>
      </div>

      <div className="mb-5">
        <SectionTitle>Contraseña principal</SectionTitle>
        <PasswordChanger onChangePassword={onChangePassword} />
      </div>
      <div>
        <SectionTitle>Contraseña de finanzas y listas</SectionTitle>
        <p className="text-xs mb-2" style={{ color: C.inkSoft }}>Esta contraseña protege esta sección y la de Finanzas.</p>
        <PasswordChanger onChangePassword={onChangePasswordAvanzada} />
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Cotizaciones: fila de item, resumen, editor y listado               */
/* ------------------------------------------------------------------ */
function ItemRow({ item, mode, hasUnidad, onChange, onRemove }) {
  const cot = hasUnidad ? (Number(item.unidades) || 0) * (Number(item.valorUnidad) || 0) : (Number(item.valor) || 0);
  const fileRef = useRef(null);
  async function handleFactura(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    try { const dataUrl = await resizeImage(file, 320); onChange({ ...item, factura: dataUrl }); } catch { /* ignore */ }
  }

  if (mode === 'cotizar') {
    return (
      <div className="rounded-xl p-3 mb-2" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
        <div className="flex gap-2 mb-2 items-center">
          <div className="flex-1"><TextInput placeholder="Nombre" value={item.nombre} onChange={e => onChange({ ...item, nombre: e.target.value })} /></div>
          {onRemove && <button onClick={onRemove} className="w-9 h-9 rounded-lg flex items-center justify-center flex-shrink-0" style={{ background: C.line }}><X size={14} /></button>}
        </div>
        {hasUnidad ? (
          <div className="grid grid-cols-3 gap-2 items-end">
            <div><span className="text-[10px]" style={{ color: C.inkSoft }}>Cantidad</span><TextInput type="number" value={item.unidades} onChange={e => onChange({ ...item, unidades: e.target.value })} /></div>
            <div><span className="text-[10px]" style={{ color: C.inkSoft }}>Valor unidad</span><TextInput type="number" value={item.valorUnidad} onChange={e => onChange({ ...item, valorUnidad: e.target.value })} /></div>
            <div className="text-right"><span className="text-[10px] block" style={{ color: C.inkSoft }}>Total</span><span className="font-semibold text-sm" style={{ color: C.ink }}>{fmtCOP(cot)}</span></div>
          </div>
        ) : (
          <div><span className="text-[10px]" style={{ color: C.inkSoft }}>Valor</span><TextInput type="number" value={item.valor} onChange={e => onChange({ ...item, valor: e.target.value })} /></div>
        )}
      </div>
    );
  }

  const hasReal = item.valorReal !== '' && item.valorReal != null;
  const diff = cot - (Number(item.valorReal) || 0);
  return (
    <div className="rounded-xl p-3 mb-2" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
      <div className="flex items-center justify-between mb-1.5 gap-2">
        <span className="font-medium text-sm truncate" style={{ color: C.ink }}>{item.nombre}</span>
        <span className="text-xs flex-shrink-0" style={{ color: C.inkSoft }}>Cotizado {fmtCOP(cot)}</span>
      </div>
      <div className="flex items-center gap-2">
        <div className="flex-1"><TextInput type="number" placeholder="Valor real" value={item.valorReal || ''} onChange={e => onChange({ ...item, valorReal: e.target.value })} /></div>
        <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={handleFactura} />
        <button onClick={() => fileRef.current?.click()} className="w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0" style={{ background: item.factura ? C.wine : C.line }}>
          <Camera size={15} color={item.factura ? '#fff' : C.ink} />
        </button>
      </div>
      {hasReal && (
        <p className="text-xs mt-1.5 text-right font-medium" style={{ color: diff >= 0 ? C.sage : C.brick }}>
          {diff >= 0 ? `Ahorraste ${fmtCOP(diff)}` : `Gastaste ${fmtCOP(Math.abs(diff))} de más`}
        </p>
      )}
    </div>
  );
}

function SummaryRow({ label, value, bold, big }) {
  return (
    <div className={`flex justify-between ${big ? 'text-base' : 'text-sm'}`} style={{ marginBottom: 4 }}>
      <span style={{ color: big ? C.wine : (bold ? C.ink : C.inkSoft), fontWeight: bold || big ? 600 : 400 }}>{label}</span>
      <span style={{ color: big ? C.wine : C.ink, fontWeight: bold || big ? 600 : 400 }}>{fmtCOP(value)}</span>
    </div>
  );
}

function PrendaCotizadaBlock({ prenda, index, onChange, onRemove, canRemove }) {
  const [expanded, setExpanded] = useState(index === 0);
  const totals = computePrendaTotals(prenda);

  const updateItem = (arrKey, id, patch) => onChange({ ...prenda, [arrKey]: prenda[arrKey].map(it => it.id === id ? { ...it, ...patch } : it) });
  const removeItem = (arrKey, id) => onChange({ ...prenda, [arrKey]: prenda[arrKey].filter(it => it.id !== id) });
  const addItem = (arrKey, base) => onChange({ ...prenda, [arrKey]: [...prenda[arrKey], { id: uid(), ...base }] });

  const telas = prenda.itemsConUnidad.filter(i => i.categoria === 'Tela');
  const insumos = prenda.itemsConUnidad.filter(i => i.categoria === 'Insumo');

  return (
    <div className="rounded-2xl mb-3 overflow-hidden" style={{ border: `1px solid ${C.line}` }}>
      <button onClick={() => setExpanded(e => !e)} className="w-full flex items-center gap-2 p-3.5" style={{ background: C.paper }}>
        <div className="flex-1 text-left min-w-0">
          <p className="font-medium truncate" style={{ color: C.ink }}>{prenda.nombre || 'Prenda sin nombre'}</p>
          <p className="text-xs" style={{ color: C.inkSoft }}>{fmtCOP(totals.totalPrenda)}</p>
        </div>
        {canRemove && (
          <span onClick={e => { e.stopPropagation(); onRemove(); }} className="w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0" style={{ background: C.line }}>
            <Trash2 size={14} style={{ color: C.brick }} />
          </span>
        )}
        <ChevronRight size={18} style={{ color: C.inkSoft, transform: expanded ? 'rotate(90deg)' : 'none', flexShrink: 0 }} />
      </button>
      {expanded && (
        <div className="p-3.5 pt-0" style={{ background: C.paper }}>
          <Field label="Nombre de la prenda" required><TextInput placeholder="Ej. Vestido Polka Dots" value={prenda.nombre} onChange={e => onChange({ ...prenda, nombre: e.target.value })} /></Field>

          <SectionTitle>Telas</SectionTitle>
          {telas.map(it => <ItemRow key={it.id} item={it} mode="cotizar" hasUnidad onChange={patch => updateItem('itemsConUnidad', it.id, patch)} onRemove={() => removeItem('itemsConUnidad', it.id)} />)}
          <button onClick={() => addItem('itemsConUnidad', { categoria: 'Tela', nombre: `Tela ${telas.length + 1}`, unidades: '', valorUnidad: '', valorReal: '', factura: '' })} className="text-sm font-medium mb-4" style={{ color: C.wine }}>+ Agregar tela</button>

          <SectionTitle>Insumos</SectionTitle>
          {insumos.map(it => <ItemRow key={it.id} item={it} mode="cotizar" hasUnidad onChange={patch => updateItem('itemsConUnidad', it.id, patch)} onRemove={() => removeItem('itemsConUnidad', it.id)} />)}
          <button onClick={() => addItem('itemsConUnidad', { categoria: 'Insumo', nombre: 'Nuevo insumo', unidades: '', valorUnidad: '', valorReal: '', factura: '' })} className="text-sm font-medium mb-4" style={{ color: C.wine }}>+ Agregar insumo</button>

          <SectionTitle>Accesorios y costos fijos</SectionTitle>
          {prenda.itemsDirectos.map(it => <ItemRow key={it.id} item={it} mode="cotizar" onChange={patch => updateItem('itemsDirectos', it.id, patch)} onRemove={() => removeItem('itemsDirectos', it.id)} />)}
          <button onClick={() => addItem('itemsDirectos', { nombre: 'Nuevo costo', valor: '', valorReal: '', factura: '' })} className="text-sm font-medium mb-4" style={{ color: C.wine }}>+ Agregar costo</button>

          <SectionTitle>Mano de obra</SectionTitle>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Corte"><TextInput type="number" value={prenda.corte} onChange={e => onChange({ ...prenda, corte: e.target.value })} /></Field>
            <Field label="Ensamble"><TextInput type="number" value={prenda.ensamble} onChange={e => onChange({ ...prenda, ensamble: e.target.value })} /></Field>
          </div>

          <SectionTitle>Márgenes</SectionTitle>
          <div className="grid grid-cols-3 gap-3">
            <Field label="Error %"><TextInput type="number" value={prenda.margenError} onChange={e => onChange({ ...prenda, margenError: e.target.value })} /></Field>
            <Field label="Ganancia %"><TextInput type="number" value={prenda.margenGanancia} onChange={e => onChange({ ...prenda, margenGanancia: e.target.value })} /></Field>
            <Field label="Comisión %"><TextInput type="number" value={prenda.comision} onChange={e => onChange({ ...prenda, comision: e.target.value })} /></Field>
          </div>

          <SectionTitle>Ajustes finales</SectionTitle>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Envío"><TextInput type="number" value={prenda.envio} onChange={e => onChange({ ...prenda, envio: e.target.value })} /></Field>
            <Field label="Descuento"><TextInput type="number" value={prenda.descuento} onChange={e => onChange({ ...prenda, descuento: e.target.value })} /></Field>
            <Field label="Impuesto"><TextInput type="number" value={prenda.impuesto} onChange={e => onChange({ ...prenda, impuesto: e.target.value })} /></Field>
            <Field label="G. Valenthina"><TextInput type="number" value={prenda.gValenthina} onChange={e => onChange({ ...prenda, gValenthina: e.target.value })} /></Field>
          </div>

          <div className="rounded-xl p-3 mb-1" style={{ background: C.cream }}>
            <SummaryRow label="Total insumos base" value={totals.totalBase} />
            <SummaryRow label={`Margen de error (${prenda.margenError || 0}%)`} value={totals.mError} />
            <SummaryRow label="Total insumos" value={totals.totalInsumos} bold />
            <SummaryRow label="Corte + Ensamble" value={totals.corte + totals.ensamble} />
            <SummaryRow label="Total producción" value={totals.totalProduccion} bold />
            <SummaryRow label={`Ganancia bruta (${prenda.margenGanancia || 0}%)`} value={totals.gananciaBruta} />
            <SummaryRow label={`Comisión (${prenda.comision || 0}%)`} value={-totals.comisionValor} />
            <SummaryRow label="Ganancia neta" value={totals.gananciaNeta} />
            <div className="h-px my-2" style={{ background: C.line }} />
            <SummaryRow label="Total de esta prenda" value={totals.totalPrenda} big />
          </div>
        </div>
      )}
    </div>
  );
}

function QuoteEditor({ initial, lists, clients, onSave, onDelete, onConvert, onClose, onCreateClient }) {
  const [q, setQ] = useState(() => initial ? normalizeQuote(initial) : { ...newQuote(), asesor: lists.asesores?.[0] || '' });
  const [clientMode, setClientMode] = useState(q.clientId ? 'existing' : 'existing');
  const [newClientName, setNewClientName] = useState('');
  const [err, setErr] = useState('');

  const totals = computeQuoteTotals(q);

  function updatePrenda(id, patch) { setQ(prev => ({ ...prev, prendas: prev.prendas.map(p => p.id === id ? patch : p) })); }
  function addPrenda() { setQ(prev => ({ ...prev, prendas: [...prev.prendas, newPrendaCotizada(`Prenda ${prev.prendas.length + 1}`)] })); }
  function removePrenda(id) { setQ(prev => ({ ...prev, prendas: prev.prendas.filter(p => p.id !== id) })); }

  function resolveClient() {
    if (q.prendas.some(p => !p.nombre.trim())) { setErr('Ponle nombre a todas las prendas'); return null; }
    if (clientMode === 'existing') {
      if (!q.clientId) { setErr('Selecciona una clienta'); return null; }
      setErr('');
      return q;
    }
    if (!newClientName.trim()) { setErr('Escribe el nombre de la nueva clienta'); return null; }
    setErr('');
    if (q.clientId) return q;
    const created = onCreateClient({ nombre: newClientName, telefono: '', instagram: '' });
    const updated = { ...q, clientId: created.id, clienteNombre: created.nombre };
    setQ(updated);
    return updated;
  }
  function handleSave() { const r = resolveClient(); if (r) onSave(r); }
  function handleConvert() { const r = resolveClient(); if (r) onConvert(r); }

  return (
    <div>
      <div className="grid grid-cols-2 gap-3">
        <Field label="Fecha"><TextInput type="date" value={q.fecha} onChange={e => setQ({ ...q, fecha: e.target.value })} /></Field>
        <Field label="Estado">
          <Select value={q.estado} onChange={e => setQ({ ...q, estado: e.target.value })}>
            {ESTADOS_COTIZACION.map(s => <option key={s.key}>{s.key}</option>)}
          </Select>
        </Field>
      </div>

      <Field label="Cliente" required>
        <div className="flex gap-2 mb-2">
          <button onClick={() => setClientMode('existing')} className="flex-1 rounded-xl py-2 text-sm font-medium" style={{ background: clientMode === 'existing' ? C.wine : C.line, color: clientMode === 'existing' ? '#fff' : C.ink }}>Existente</button>
          <button onClick={() => setClientMode('new')} className="flex-1 rounded-xl py-2 text-sm font-medium" style={{ background: clientMode === 'new' ? C.wine : C.line, color: clientMode === 'new' ? '#fff' : C.ink }}>Nueva clienta</button>
        </div>
        {clientMode === 'existing' ? (
          <Select value={q.clientId} onChange={e => { const c = clients.find(x => x.id === e.target.value); setQ({ ...q, clientId: e.target.value, clienteNombre: c?.nombre || '' }); }}>
            <option value="">Selecciona una clienta…</option>
            {clients.map(c => <option key={c.id} value={c.id}>{c.nombre} ({c.codigo})</option>)}
          </Select>
        ) : (
          <TextInput placeholder="Nombre de la nueva clienta" value={newClientName} onChange={e => setNewClientName(e.target.value)} />
        )}
      </Field>

      <Field label="Cotizado por">
        <Select value={q.asesor} onChange={e => setQ({ ...q, asesor: e.target.value })}>
          <option value="">Sin asignar</option>
          {lists.asesores.map(o => <option key={o}>{o}</option>)}
        </Select>
      </Field>

      <SectionTitle>Prendas a cotizar ({q.prendas.length})</SectionTitle>
      {q.prendas.map((p, i) => (
        <PrendaCotizadaBlock key={p.id} prenda={p} index={i} onChange={patch => updatePrenda(p.id, patch)} onRemove={() => removePrenda(p.id)} canRemove={q.prendas.length > 1} />
      ))}
      <button onClick={addPrenda} className="text-sm font-medium mb-4" style={{ color: C.wine }}>+ Agregar otra prenda</button>

      <Field label="Notas"><TextArea placeholder="Notas sobre esta cotización…" value={q.notas} onChange={e => setQ({ ...q, notas: e.target.value })} /></Field>

      <div className="rounded-2xl p-4 mb-4" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
        <SummaryRow label={`Total (${q.prendas.length} prenda${q.prendas.length !== 1 ? 's' : ''})`} value={totals.totalPrenda} big />
      </div>

      {err && <p className="text-sm mb-2" style={{ color: C.brick }}>{err}</p>}

      <div className="flex gap-2 mt-4">
        {initial && <button onClick={() => onDelete(q)} className="rounded-xl py-2.5 px-4" style={{ color: C.brick }}><Trash2 size={18} /></button>}
        <GhostButton full onClick={onClose}>Cerrar</GhostButton>
        <PrimaryButton full onClick={handleSave}>Guardar</PrimaryButton>
      </div>
      {q.estado !== 'Convertida a pedido' && (
        <button onClick={handleConvert} className="w-full rounded-xl py-2.5 mt-2 text-sm font-medium" style={{ background: C.gold, color: C.ink }}>
          Convertir en pedido{q.prendas.length > 1 ? 's' : ''}
        </button>
      )}
      {q.orderIds?.length > 0 && <p className="text-xs text-center mt-2" style={{ color: C.inkSoft }}>Ya se convirtió en {q.orderIds.length} pedido{q.orderIds.length !== 1 ? 's' : ''}</p>}
    </div>
  );
}

function Cotizaciones({ quotes, onOpen, onNew }) {
  const sorted = quotes.slice().sort((a, b) => (b.fecha || '').localeCompare(a.fecha || ''));
  return (
    <div>
      {sorted.length === 0
        ? <EmptyState icon={Calculator} title="Sin cotizaciones" subtitle="Crea tu primera cotización con el botón de abajo" />
        : sorted.map(q => {
          const totals = computeQuoteTotals(q);
          const estado = ESTADOS_COTIZACION.find(e => e.key === q.estado) || ESTADOS_COTIZACION[0];
          return (
            <button key={q.id} onClick={() => onOpen(q)} className="w-full text-left rounded-2xl p-3.5 mb-2.5" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
              <div className="flex items-center justify-between mb-1">
                <span className="text-xs" style={{ color: C.inkSoft }}>{fmtDate(q.fecha)}</span>
                <Badge bg={estado.color}>{q.estado}</Badge>
              </div>
              <p className="font-medium truncate" style={{ color: C.ink }}>{q.prendas.length > 1 ? `${q.prendas.length} prendas` : (q.prendas[0]?.nombre || 'Prenda sin nombre')}</p>
              <p className="text-sm truncate" style={{ color: C.inkSoft }}>{q.clienteNombre || 'Sin cliente'}</p>
              {q.asesor && <p className="text-xs truncate mb-1" style={{ color: C.inkSoft }}>Cotizado por {q.asesor}</p>}
              <p className="text-sm font-semibold" style={{ color: C.wine }}>{fmtCOP(totals.totalPrenda)}</p>
            </button>
          );
        })}
      <button onClick={onNew} className="w-full rounded-xl py-3 font-medium mt-1" style={{ background: C.wine, color: '#fff' }}>+ Nueva cotización</button>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Medidas personalizadas                                              */
/* ------------------------------------------------------------------ */
const MEDIDA_FIELDS = [
  { key: 'talleLargoEspalda', label: 'Talle largo espalda' },
  { key: 'talleLargoDelantero', label: 'Talle largo delantero' },
  { key: 'anchoEspalda', label: 'Ancho espalda' },
  { key: 'anchoDelantero', label: 'Ancho delantero' },
  { key: 'escote', label: 'Escote' },
  { key: 'hombro', label: 'Hombro' },
  { key: 'contornoBusto', label: 'Contorno busto' },
  { key: 'bajoBusto', label: 'Bajo busto' },
  { key: 'distanciaBusto', label: 'Distancia busto' },
  { key: 'contornoCintura', label: 'Contorno cintura' },
  { key: 'contornoCadera', label: 'Contorno cadera' },
  { key: 'largoManga', label: 'Largo manga' },
  { key: 'anchoManga', label: 'Ancho manga' },
  { key: 'largoBlusa', label: 'Largo blusa' },
  { key: 'largoVestido', label: 'Largo vestido' },
  { key: 'imperio', label: 'Imperio' },
  { key: 'bajoImperio', label: 'Bajo imperio' },
  { key: 'largoVestidoDesdeCintura', label: 'Largo vestido desde cintura' },
];

function Medidas({ clients, onSaveMedidas }) {
  const [clientId, setClientId] = useState('');
  const [form, setForm] = useState({});
  const [extras, setExtras] = useState([]);
  const [saved, setSaved] = useState(false);

  function selectClient(id) {
    setClientId(id);
    setSaved(false);
    const c = clients.find(x => x.id === id);
    const m = c?.medidas || {};
    const base = {};
    MEDIDA_FIELDS.forEach(f => { base[f.key] = m[f.key] || ''; });
    setForm(base);
    setExtras(m.extras || []);
  }

  function addExtra() { setExtras([...extras, { id: uid(), nombre: '', valor: '' }]); }
  function updateExtra(id, patch) { setExtras(extras.map(e => e.id === id ? { ...e, ...patch } : e)); }
  function removeExtra(id) { setExtras(extras.filter(e => e.id !== id)); }

  function handleSave() {
    if (!clientId) return;
    onSaveMedidas(clientId, { ...form, extras });
    setSaved(true);
  }

  function handleDownload() {
    const c = clients.find(x => x.id === clientId);
    const lines = [`Medidas de ${c?.nombre || 'clienta'}`, ''];
    MEDIDA_FIELDS.forEach(f => lines.push(`${f.label}: ${form[f.key] || ''}`));
    extras.forEach(e => lines.push(`${e.nombre || 'Medida adicional'}: ${e.valor || ''}`));
    downloadText(`Medidas_${(c?.nombre || 'clienta').replace(/\s+/g, '_')}.txt`, lines.join('\n'));
  }

  const selectedClient = clients.find(c => c.id === clientId);

  return (
    <div className="pb-6">
      <Field label="Clienta">
        <Select value={clientId} onChange={e => selectClient(e.target.value)}>
          <option value="">Selecciona una clienta…</option>
          {clients.map(c => <option key={c.id} value={c.id}>{c.nombre} ({c.codigo})</option>)}
        </Select>
      </Field>

      {!clientId ? (
        <p className="text-sm px-1" style={{ color: C.inkSoft }}>Elige una clienta para ver o llenar sus medidas.</p>
      ) : (
        <>
          <div className="grid grid-cols-2 gap-3">
            {MEDIDA_FIELDS.map(f => (
              <Field key={f.key} label={f.label}>
                <TextInput placeholder="cm" value={form[f.key] || ''} onChange={e => setForm({ ...form, [f.key]: e.target.value })} />
              </Field>
            ))}
          </div>

          {extras.length > 0 && <SectionTitle>Medidas adicionales</SectionTitle>}
          {extras.map(ex => (
            <div key={ex.id} className="flex gap-2 mb-2">
              <div className="flex-1"><TextInput placeholder="Nombre de la medida" value={ex.nombre} onChange={e => updateExtra(ex.id, { nombre: e.target.value })} /></div>
              <div className="w-24"><TextInput placeholder="cm" value={ex.valor} onChange={e => updateExtra(ex.id, { valor: e.target.value })} /></div>
              <button onClick={() => removeExtra(ex.id)} className="w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0" style={{ background: C.line }}><X size={14} /></button>
            </div>
          ))}
          <button onClick={addExtra} className="text-sm font-medium mb-4" style={{ color: C.wine }}>+ Agregar otra medida</button>

          {saved && <p className="text-sm mb-2" style={{ color: C.sage }}>Medidas guardadas para {selectedClient?.nombre}.</p>}
          <div className="flex gap-2 mt-2">
            <GhostButton full onClick={handleDownload}>Descargar tabla</GhostButton>
            <PrimaryButton full onClick={handleSave}>Guardar medidas</PrimaryButton>
          </div>
        </>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Costos reales de un pedido (después de confirmado)                  */
/* ------------------------------------------------------------------ */
function OrderCostsEditor({ order, onSave, onClose }) {
  const [costos, setCostos] = useState(order.costos);

  if (!costos) {
    return (
      <div>
        <p className="text-sm mb-4" style={{ color: C.inkSoft }}>Este pedido no viene de una cotización, así que no tiene un desglose de costos para comparar.</p>
        <GhostButton full onClick={onClose}>Cerrar</GhostButton>
      </div>
    );
  }

  const totals = computeRealTotals(costos);
  const updateItem = (arrKey, id, patch) => setCostos(prev => ({ ...prev, [arrKey]: prev[arrKey].map(it => it.id === id ? { ...it, ...patch } : it) }));
  const telas = costos.itemsConUnidad.filter(i => i.categoria === 'Tela');
  const insumos = costos.itemsConUnidad.filter(i => i.categoria === 'Insumo');

  return (
    <div>
      <p className="text-sm mb-4" style={{ color: C.inkSoft }}>Registra aquí lo que en realidad gastaste comprando la tela y los insumos de este pedido, con la factura si quieres.</p>
      <div className="rounded-xl px-3 py-2.5 mb-4 flex items-center justify-between" style={{ background: totals.count === 0 ? C.line : totals.diff >= 0 ? '#E4EBE1' : '#F7E6E1' }}>
        <span className="text-sm" style={{ color: C.inkSoft }}>{totals.count === 0 ? 'Sin datos reales aún' : totals.diff >= 0 ? 'Ganaste en insumos' : 'Sobrecosto en insumos'}</span>
        {totals.count > 0 && <span className="font-semibold" style={{ color: totals.diff >= 0 ? C.sage : C.brick }}>{fmtCOP(Math.abs(totals.diff))}</span>}
      </div>
      <SectionTitle>Telas</SectionTitle>
      {telas.map(it => <ItemRow key={it.id} item={it} mode="real" hasUnidad onChange={patch => updateItem('itemsConUnidad', it.id, patch)} />)}
      <SectionTitle>Insumos</SectionTitle>
      {insumos.map(it => <ItemRow key={it.id} item={it} mode="real" hasUnidad onChange={patch => updateItem('itemsConUnidad', it.id, patch)} />)}
      <SectionTitle>Accesorios y costos fijos</SectionTitle>
      {costos.itemsDirectos.map(it => <ItemRow key={it.id} item={it} mode="real" onChange={patch => updateItem('itemsDirectos', it.id, patch)} />)}
      <SectionTitle>Mano de obra</SectionTitle>
      <ItemRow item={{ nombre: 'Corte', valor: costos.corte, valorReal: costos.corteReal, factura: costos.corteFactura }} mode="real" onChange={patch => setCostos({ ...costos, corteReal: patch.valorReal, corteFactura: patch.factura })} />
      <ItemRow item={{ nombre: 'Ensamble', valor: costos.ensamble, valorReal: costos.ensambleReal, factura: costos.ensambleFactura }} mode="real" onChange={patch => setCostos({ ...costos, ensambleReal: patch.valorReal, ensambleFactura: patch.factura })} />
      <div className="flex gap-2 mt-4">
        <GhostButton full onClick={onClose}>Cerrar</GhostButton>
        <PrimaryButton full onClick={() => onSave(costos)}>Guardar costos reales</PrimaryButton>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Colecciones e inventario (prendas ya hechas)                        */
/* ------------------------------------------------------------------ */
function ProductForm({ initial, lists, onSave, onCancel, onDelete }) {
  const [f, setF] = useState(initial || { nombre: '', categoria: lists.categorias[0] || '', talla: lists.tallas[0] || '', tela: lists.telas[0] || '', color: lists.colores[0] || '', detalles: '', precio: '', disponible: '1', foto: '' });
  const [err, setErr] = useState('');
  const fileRef = useRef(null);

  async function handlePhoto(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    try { const dataUrl = await resizeImage(file); setF(prev => ({ ...prev, foto: dataUrl })); } catch { /* ignore */ }
  }
  function submit() {
    if (!f.nombre.trim()) { setErr('Escribe el nombre de la prenda'); return; }
    if (!f.precio || Number(f.precio) <= 0) { setErr('Escribe un precio válido'); return; }
    onSave({ ...f, precio: Number(f.precio) || 0, disponible: Number(f.disponible) || 0 });
  }

  return (
    <div>
      <Field label="Nombre" required><TextInput placeholder="Ej. Vestido Coquette" value={f.nombre} onChange={e => setF({ ...f, nombre: e.target.value })} /></Field>
      <div className="grid grid-cols-2 gap-3">
        <Field label="Categoría"><Select value={f.categoria} onChange={e => setF({ ...f, categoria: e.target.value })}>{lists.categorias.map(o => <option key={o}>{o}</option>)}</Select></Field>
        <Field label="Talla"><Select value={f.talla} onChange={e => setF({ ...f, talla: e.target.value })}>{lists.tallas.map(o => <option key={o}>{o}</option>)}</Select></Field>
        <Field label="Tela"><Select value={f.tela} onChange={e => setF({ ...f, tela: e.target.value })}>{lists.telas.map(o => <option key={o}>{o}</option>)}</Select></Field>
        <Field label="Color"><Select value={f.color} onChange={e => setF({ ...f, color: e.target.value })}>{lists.colores.map(o => <option key={o}>{o}</option>)}</Select></Field>
      </div>
      <Field label="Detalles"><TextArea placeholder="Detalles de la prenda…" value={f.detalles} onChange={e => setF({ ...f, detalles: e.target.value })} /></Field>
      <div className="grid grid-cols-2 gap-3">
        <Field label="Precio" required><TextInput type="number" value={f.precio} onChange={e => setF({ ...f, precio: e.target.value })} /></Field>
        <Field label="Disponibles"><TextInput type="number" value={f.disponible} onChange={e => setF({ ...f, disponible: e.target.value })} /></Field>
      </div>
      <Field label="Foto">
        <input ref={fileRef} type="file" accept="image/*" onChange={handlePhoto} className="hidden" />
        <button onClick={() => fileRef.current?.click()} className="w-full rounded-xl py-3 flex items-center justify-center gap-2 border" style={{ borderColor: C.line, borderStyle: 'dashed' }}>
          {f.foto ? <img src={f.foto} className="w-10 h-10 rounded-lg object-cover" /> : <Camera size={18} style={{ color: C.inkSoft }} />}
          <span className="text-sm" style={{ color: C.inkSoft }}>{f.foto ? 'Cambiar foto' : 'Agregar foto'}</span>
        </button>
      </Field>
      {err && <p className="text-sm mb-2" style={{ color: C.brick }}>{err}</p>}
      <div className="flex gap-2 mt-4">
        {initial && <button onClick={() => onDelete(initial)} className="rounded-xl py-2.5 px-4" style={{ color: C.brick }}><Trash2 size={18} /></button>}
        <GhostButton full onClick={onCancel}>Cancelar</GhostButton>
        <PrimaryButton full onClick={submit}>Guardar</PrimaryButton>
      </div>
    </div>
  );
}

function Inventario({ catalog, lists, onChange }) {
  const [selColeccion, setSelColeccion] = useState(catalog.colecciones[0]?.id || '');
  const [newColeccion, setNewColeccion] = useState('');
  const [productModal, setProductModal] = useState(null); // { mode, product }

  function addColeccion() {
    const nombre = newColeccion.trim();
    if (!nombre) return;
    const c = { id: uid(), nombre, prendas: [] };
    onChange({ colecciones: [...catalog.colecciones, c] });
    setNewColeccion('');
    setSelColeccion(c.id);
  }
  function removeColeccion(id) {
    onChange({ colecciones: catalog.colecciones.filter(c => c.id !== id) });
    if (selColeccion === id) setSelColeccion((catalog.colecciones.find(c => c.id !== id) || {}).id || '');
  }
  function saveProduct(p) {
    onChange({
      colecciones: catalog.colecciones.map(c => c.id !== selColeccion ? c : {
        ...c,
        prendas: productModal.mode === 'edit' ? c.prendas.map(x => x.id === p.id ? p : x) : [...c.prendas, { id: uid(), ...p }],
      }),
    });
    setProductModal(null);
  }
  function deleteProduct(p) {
    onChange({ colecciones: catalog.colecciones.map(c => c.id !== selColeccion ? c : { ...c, prendas: c.prendas.filter(x => x.id !== p.id) }) });
    setProductModal(null);
  }

  const coleccion = catalog.colecciones.find(c => c.id === selColeccion);

  return (
    <div className="pb-6">
      <div className="flex gap-2 mb-3 overflow-x-auto pb-1">
        {catalog.colecciones.map(c => (
          <button key={c.id} onClick={() => setSelColeccion(c.id)} className="flex-shrink-0 rounded-full px-3 py-1.5 text-xs font-medium" style={{ background: selColeccion === c.id ? C.wine : C.line, color: selColeccion === c.id ? '#fff' : C.ink }}>
            {c.nombre} ({c.prendas.length})
          </button>
        ))}
      </div>
      <div className="flex gap-2 mb-5">
        <TextInput placeholder="Nueva colección (ej. Verano 2027)" value={newColeccion} onChange={e => setNewColeccion(e.target.value)} onKeyDown={e => e.key === 'Enter' && addColeccion()} />
        <button onClick={addColeccion} className="w-11 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: C.wine }}><Plus size={18} color="#fff" /></button>
      </div>

      {!coleccion ? (
        <EmptyState icon={Package} title="Sin colecciones" subtitle="Crea tu primera colección arriba" />
      ) : (
        <>
          <div className="flex items-center justify-between mb-2">
            <SectionTitle>{coleccion.nombre}</SectionTitle>
            {catalog.colecciones.length > 1 && <button onClick={() => removeColeccion(coleccion.id)} className="text-xs" style={{ color: C.brick }}>Eliminar colección</button>}
          </div>
          {coleccion.prendas.length === 0
            ? <p className="text-sm px-1 mb-3" style={{ color: C.inkSoft }}>Sin prendas todavía.</p>
            : coleccion.prendas.map(p => (
              <button key={p.id} onClick={() => setProductModal({ mode: 'edit', product: p })} className="w-full text-left rounded-2xl p-3.5 flex gap-3 mb-2.5" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
                <div className="w-14 h-14 rounded-xl flex-shrink-0 overflow-hidden flex items-center justify-center" style={{ background: C.cream }}>
                  {p.foto ? <img src={p.foto} className="w-full h-full object-cover" /> : <ImageOff size={16} style={{ color: C.inkSoft }} />}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-medium truncate" style={{ color: C.ink }}>{p.nombre}</p>
                  <p className="text-xs truncate" style={{ color: C.inkSoft }}>{[p.talla, p.color, p.tela].filter(Boolean).join(' · ')}</p>
                  <div className="flex items-center gap-1.5 mt-1">
                    <Badge bg={Number(p.disponible) > 0 ? '#E4EBE1' : '#F7E6E1'} fg={Number(p.disponible) > 0 ? C.sage : C.brick}>{p.disponible || 0} disponibles</Badge>
                    <Badge bg={C.line} fg={C.ink}>{fmtCOP(p.precio)}</Badge>
                  </div>
                </div>
              </button>
            ))}
          <button onClick={() => setProductModal({ mode: 'new', product: null })} className="w-full rounded-xl py-3 font-medium mt-1" style={{ background: C.wine, color: '#fff' }}>+ Nueva prenda</button>
        </>
      )}

      {productModal && (
        <Sheet title={productModal.mode === 'edit' ? 'Editar prenda' : 'Nueva prenda'} onClose={() => setProductModal(null)}>
          <ProductForm initial={productModal.product} lists={lists} onSave={saveProduct} onCancel={() => setProductModal(null)} onDelete={deleteProduct} />
        </Sheet>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Metas                                                               */
