function Metas({ goals, orders, onChange }) {
  const [form, setForm] = useState({ nombre: '', tipo: 'pedidos', objetivo: '', fechaInicio: '', fechaFin: '' });

  function addGoal() {
    if (!form.nombre.trim() || !form.objetivo) return;
    onChange([...goals, { id: uid(), ...form, objetivo: Number(form.objetivo) || 0 }]);
    setForm({ nombre: '', tipo: 'pedidos', objetivo: '', fechaInicio: '', fechaFin: '' });
  }
  function removeGoal(id) { onChange(goals.filter(g => g.id !== id)); }

  return (
    <div className="pb-6">
      <SectionTitle>Nueva meta</SectionTitle>
      <div className="rounded-2xl p-4 mb-5" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
        <Field label="Nombre de la meta"><TextInput placeholder="Ej. Vestidos de octubre" value={form.nombre} onChange={e => setForm({ ...form, nombre: e.target.value })} /></Field>
        <Field label="Tipo de meta">
          <Select value={form.tipo} onChange={e => setForm({ ...form, tipo: e.target.value })}>
            <option value="pedidos">Cantidad de pedidos</option>
            <option value="ingresos">Ingresos ($)</option>
          </Select>
        </Field>
        <Field label={form.tipo === 'ingresos' ? 'Meta en pesos' : 'Meta en pedidos'}>
          <TextInput type="number" value={form.objetivo} onChange={e => setForm({ ...form, objetivo: e.target.value })} />
        </Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Desde"><TextInput type="date" value={form.fechaInicio} onChange={e => setForm({ ...form, fechaInicio: e.target.value })} /></Field>
          <Field label="Hasta"><TextInput type="date" value={form.fechaFin} onChange={e => setForm({ ...form, fechaFin: e.target.value })} /></Field>
        </div>
        <PrimaryButton full onClick={addGoal}>Agregar meta</PrimaryButton>
      </div>

      <SectionTitle>Tus metas</SectionTitle>
      {goals.length === 0
        ? <p className="text-sm px-1" style={{ color: C.inkSoft }}>Aún no has creado metas.</p>
        : goals.slice().sort((a, b) => (b.fechaInicio || '').localeCompare(a.fechaInicio || '')).map(g => {
          const p = computeGoalProgress(g, orders);
          return (
            <div key={g.id} className="rounded-2xl p-3.5 mb-2.5" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
              <div className="flex items-center justify-between mb-1">
                <p className="font-medium" style={{ color: C.ink }}>{g.nombre}</p>
                <button onClick={() => removeGoal(g.id)} className="w-7 h-7 rounded-full flex items-center justify-center" style={{ background: C.line }}><X size={13} /></button>
              </div>
              <p className="text-xs mb-2" style={{ color: C.inkSoft }}>{g.fechaInicio ? fmtDate(g.fechaInicio) : '—'} · {g.fechaFin ? fmtDate(g.fechaFin) : '—'}</p>
              <div className="h-2 rounded-full overflow-hidden mb-1" style={{ background: C.line }}>
                <div className="h-full rounded-full" style={{ width: `${p.pct}%`, background: p.cumplida ? C.sage : C.wine }} />
              </div>
              <div className="flex items-center justify-between text-xs">
                <span style={{ color: C.inkSoft }}>{g.tipo === 'ingresos' ? `${fmtCOP(p.actual)} de ${fmtCOP(p.objetivo)}` : `${p.actual} de ${p.objetivo} pedidos`}</span>
                <Badge bg={p.cumplida ? '#E4EBE1' : C.line} fg={p.cumplida ? C.sage : C.inkSoft}>{p.cumplida ? 'Cumplida' : `${p.pct}%`}</Badge>
              </div>
            </div>
          );
        })}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Más (tab hub: pagos / calendario / cotizaciones / medidas / listas) */
/* ------------------------------------------------------------------ */
/* ------------------------------------------------------------------ */
/*  Finanzas (protegida con contraseña avanzada)                        */
/* ------------------------------------------------------------------ */
function computeOrderProfit(order) {
  if (!order.costos) return null;
  const rt = computeRealTotals(order.costos);
  if (rt.count === 0) return null;
  return { realCost: rt.real, ganancia: (Number(order.precio) || 0) - rt.real };
}
function gastoMensualizado(g) {
  const m = Number(g.monto) || 0;
  if (g.frecuencia === 'Semanal') return m * 4.33;
  if (g.frecuencia === 'Anual') return m / 12;
  if (g.frecuencia === 'Único') return 0;
  return m; // Mensual
}
function monthsAvailable(orders, transactions) {
  const set = new Set();
  orders.forEach(o => { if (o.createdAt) set.add(o.createdAt.slice(0, 7)); });
  (transactions || []).forEach(t => { if (t.fecha) set.add(t.fecha.slice(0, 7)); });
  set.add(new Date().toISOString().slice(0, 7));
  return Array.from(set).sort().reverse();
}
function computeMonthSummary(mes, orders, transactions, gastosFijos) {
  const ordersMes = orders.filter(o => (o.createdAt || '').slice(0, 7) === mes);
  const ventas = ordersMes.reduce((s, o) => s + (Number(o.precio) || 0), 0);
  const costosRealesMes = ordersMes.reduce((s, o) => { const p = computeOrderProfit(o); return p ? s + p.realCost : s; }, 0);
  const txMes = (transactions || []).filter(t => (t.fecha || '').slice(0, 7) === mes);
  const ingresosManual = txMes.filter(t => t.tipo === 'ingreso').reduce((s, t) => s + (Number(t.monto) || 0), 0);
  const egresosManual = txMes.filter(t => t.tipo === 'egreso').reduce((s, t) => s + (Number(t.monto) || 0), 0);
  const gastosFijosMes = (gastosFijos || []).filter(g => g.activo !== false).reduce((s, g) => s + gastoMensualizado(g), 0);
  const ingresos = ventas + ingresosManual;
  const egresos = costosRealesMes + egresosManual + gastosFijosMes;
  return { mes, ingresos, egresos, ganancia: ingresos - egresos, ventas, ingresosManual, costosRealesMes, egresosManual, gastosFijosMes, pedidos: ordersMes.length };
}

function FinanzasResumen({ orders, gastosFijos, transactions }) {
  const totalVendido = orders.reduce((s, o) => s + (Number(o.precio) || 0), 0);
  const totalRecibido = orders.reduce((s, o) => s + (Number(o.abono) || 0), 0);
  const totalPendiente = totalVendido - totalRecibido;
  const conCostos = orders.map(o => ({ o, profit: computeOrderProfit(o) })).filter(x => x.profit);
  const totalCostosReales = conCostos.reduce((s, x) => s + x.profit.realCost, 0);
  const totalGananciaPedidos = conCostos.reduce((s, x) => s + x.profit.ganancia, 0);
  const ingresosManual = (transactions || []).filter(t => t.tipo === 'ingreso').reduce((s, t) => s + (Number(t.monto) || 0), 0);
  const egresosManual = (transactions || []).filter(t => t.tipo === 'egreso').reduce((s, t) => s + (Number(t.monto) || 0), 0);
  const totalGastosFijosMensual = (gastosFijos || []).filter(g => g.activo !== false).reduce((s, g) => s + gastoMensualizado(g), 0);
  const balanceCaja = totalRecibido + ingresosManual - egresosManual;

  const enEfectivo = orders.reduce((s, o) => ((o.medioPago || 'Efectivo') === 'Efectivo' ? s + (Number(o.abono) || 0) : s), 0)
    + (transactions || []).reduce((s, t) => {
      if ((t.medioPago || 'Efectivo') !== 'Efectivo') return s;
      return s + (t.tipo === 'ingreso' ? (Number(t.monto) || 0) : -(Number(t.monto) || 0));
    }, 0);
  const enTransferencias = orders.reduce((s, o) => ((o.medioPago || 'Efectivo') !== 'Efectivo' ? s + (Number(o.abono) || 0) : s), 0)
    + (transactions || []).reduce((s, t) => {
      if ((t.medioPago || 'Efectivo') === 'Efectivo') return s;
      return s + (t.tipo === 'ingreso' ? (Number(t.monto) || 0) : -(Number(t.monto) || 0));
    }, 0);

  return (
    <div className="pb-6">
      <SectionTitle>Dinero por medio de pago</SectionTitle>
      <div className="grid grid-cols-2 gap-3 mb-3">
        <StatCard label="En efectivo" value={fmtCOP(enEfectivo)} accent={enEfectivo >= 0 ? C.sage : C.brick} />
        <StatCard label="En transferencias" value={fmtCOP(enTransferencias)} accent={enTransferencias >= 0 ? C.sage : C.brick} />
      </div>
      <p className="text-xs px-1 mb-5" style={{ color: C.inkSoft }}>Incluye los abonos de tus pedidos y los movimientos manuales, cada uno según el medio de pago que le pusiste.</p>

      <SectionTitle>Ventas y producción</SectionTitle>
      <div className="grid grid-cols-2 gap-3 mb-3">
        <StatCard label="Total vendido" value={fmtCOP(totalVendido)} small />
        <StatCard label="Total recibido" value={fmtCOP(totalRecibido)} small accent={C.sage} />
        <StatCard label="Por cobrar" value={fmtCOP(totalPendiente)} small accent={C.brick} />
        <StatCard label="Costos reales" value={fmtCOP(totalCostosReales)} small />
      </div>
      <StatCard label="Ganancia real de pedidos" value={fmtCOP(totalGananciaPedidos)} accent={totalGananciaPedidos >= 0 ? C.sage : C.brick} />

      <SectionTitle>Caja general</SectionTitle>
      <div className="grid grid-cols-2 gap-3 mb-3">
        <StatCard label="Ingresos manuales" value={fmtCOP(ingresosManual)} small accent={C.sage} />
        <StatCard label="Egresos manuales" value={fmtCOP(egresosManual)} small accent={C.brick} />
        <StatCard label="Gastos fijos / mes" value={fmtCOP(totalGastosFijosMensual)} small />
        <StatCard label="Balance de caja" value={fmtCOP(balanceCaja)} small accent={balanceCaja >= 0 ? C.sage : C.brick} />
      </div>

      <SectionTitle>Ganancia por pedido</SectionTitle>
      {conCostos.length === 0
        ? <p className="text-sm px-1" style={{ color: C.inkSoft }}>Aún no has registrado costos reales en ningún pedido.</p>
        : conCostos.slice().sort((a, b) => (b.o.createdAt || '').localeCompare(a.o.createdAt || '')).map(({ o, profit }) => (
          <div key={o.id} className="rounded-2xl p-3.5 mb-2.5 flex items-center justify-between gap-2" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
            <div className="min-w-0">
              <p className="font-medium truncate" style={{ color: C.ink }}>{o.prenda}</p>
              <p className="text-xs" style={{ color: C.inkSoft }}>{o.codigo}</p>
            </div>
            <p className="font-semibold flex-shrink-0" style={{ color: profit.ganancia >= 0 ? C.sage : C.brick }}>{fmtCOP(profit.ganancia)}</p>
          </div>
        ))}
    </div>
  );
}

function FinanzasResumenMensual({ orders, transactions, gastosFijos }) {
  const meses = monthsAvailable(orders, transactions);
  return (
    <div className="pb-6">
      <SectionTitle>Resumen por mes</SectionTitle>
      {meses.map(mes => {
        const s = computeMonthSummary(mes, orders, transactions, gastosFijos);
        const [y, m] = mes.split('-');
        const label = new Date(Number(y), Number(m) - 1, 1).toLocaleDateString('es-CO', { month: 'long', year: 'numeric' });
        return (
          <div key={mes} className="rounded-2xl p-4 mb-3" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
            <p className="font-semibold capitalize mb-2" style={{ color: C.ink, fontFamily: 'Georgia, serif' }}>{label}</p>
            <SummaryRow label="Ventas de pedidos" value={s.ventas} />
            <SummaryRow label="Ingresos manuales" value={s.ingresosManual} />
            <SummaryRow label="Costos reales de pedidos" value={-s.costosRealesMes} />
            <SummaryRow label="Egresos manuales" value={-s.egresosManual} />
            <SummaryRow label="Gastos fijos (mensualizados)" value={-s.gastosFijosMes} />
            <div className="h-px my-1.5" style={{ background: C.line }} />
            <SummaryRow label="Ganancia del mes" value={s.ganancia} big />
            <p className="text-xs mt-1" style={{ color: C.inkSoft }}>{s.pedidos} pedido{s.pedidos !== 1 ? 's' : ''} creado{s.pedidos !== 1 ? 's' : ''} este mes</p>
          </div>
        );
      })}
    </div>
  );
}

function FinanzasMovimientos({ transactions, onChange, lists, onListsChange }) {
  const [form, setForm] = useState({ fecha: new Date().toISOString().slice(0, 10), tipo: 'ingreso', concepto: '', monto: '', medioPago: 'Efectivo', categoria: '', notas: '' });
  const [addingCuenta, setAddingCuenta] = useState(false);
  const [nuevaCuenta, setNuevaCuenta] = useState('');
  const cuentas = (lists.cuentas && lists.cuentas.length) ? lists.cuentas : ['Efectivo'];

  function addCuenta() {
    const v = nuevaCuenta.trim();
    if (!v) return;
    if (!cuentas.includes(v)) onListsChange({ ...lists, cuentas: [...cuentas, v] });
    setForm({ ...form, medioPago: v });
    setNuevaCuenta('');
    setAddingCuenta(false);
  }
  function addTx() {
    if (!form.concepto.trim() || !form.monto) return;
    onChange([...transactions, { id: uid(), ...form, monto: Number(form.monto) || 0 }]);
    setForm({ fecha: new Date().toISOString().slice(0, 10), tipo: 'ingreso', concepto: '', monto: '', medioPago: form.medioPago, categoria: '', notas: '' });
  }
  function removeTx(id) { onChange(transactions.filter(t => t.id !== id)); }

  const sorted = transactions.slice().sort((a, b) => (b.fecha || '').localeCompare(a.fecha || ''));
  const totalIngresos = transactions.filter(t => t.tipo === 'ingreso').reduce((s, t) => s + (Number(t.monto) || 0), 0);
  const totalEgresos = transactions.filter(t => t.tipo === 'egreso').reduce((s, t) => s + (Number(t.monto) || 0), 0);

  return (
    <div className="pb-6">
      <div className="grid grid-cols-2 gap-3 mb-4">
        <StatCard label="Ingresos" value={fmtCOP(totalIngresos)} small accent={C.sage} />
        <StatCard label="Egresos" value={fmtCOP(totalEgresos)} small accent={C.brick} />
      </div>

      <SectionTitle>Nuevo movimiento</SectionTitle>
      <div className="rounded-2xl p-4 mb-5" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
        <div className="flex gap-2 mb-3">
          <button onClick={() => setForm({ ...form, tipo: 'ingreso', categoria: '' })} className="flex-1 rounded-xl py-2 text-sm font-medium" style={{ background: form.tipo === 'ingreso' ? C.sage : C.line, color: form.tipo === 'ingreso' ? '#fff' : C.ink }}>Ingreso</button>
          <button onClick={() => setForm({ ...form, tipo: 'egreso' })} className="flex-1 rounded-xl py-2 text-sm font-medium" style={{ background: form.tipo === 'egreso' ? C.brick : C.line, color: form.tipo === 'egreso' ? '#fff' : C.ink }}>Egreso</button>
        </div>
        <Field label="Concepto"><TextInput placeholder="Ej. Venta de tela sobrante" value={form.concepto} onChange={e => setForm({ ...form, concepto: e.target.value })} /></Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Monto"><TextInput type="number" value={form.monto} onChange={e => setForm({ ...form, monto: e.target.value })} /></Field>
          <Field label="Fecha"><TextInput type="date" value={form.fecha} onChange={e => setForm({ ...form, fecha: e.target.value })} /></Field>
        </div>

        <Field label="Medio de pago">
          {!addingCuenta ? (
            <div className="flex gap-2">
              <div className="flex-1">
                <Select value={form.medioPago} onChange={e => setForm({ ...form, medioPago: e.target.value })}>
                  {cuentas.map(c => <option key={c}>{c}</option>)}
                </Select>
              </div>
              <button onClick={() => setAddingCuenta(true)} className="w-11 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: C.line }}><Plus size={16} /></button>
            </div>
          ) : (
            <div className="flex gap-2">
              <div className="flex-1"><TextInput placeholder="Ej. Bancolombia Ahorros" value={nuevaCuenta} onChange={e => setNuevaCuenta(e.target.value)} onKeyDown={e => e.key === 'Enter' && addCuenta()} /></div>
              <button onClick={addCuenta} className="w-11 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: C.wine }}><Check size={16} color="#fff" /></button>
            </div>
          )}
        </Field>

        {form.tipo === 'egreso' && (
          <Field label="Tipo de gasto">
            <Select value={form.categoria} onChange={e => setForm({ ...form, categoria: e.target.value })}>
              <option value="">Selecciona…</option>
              <option>Gasto fijo</option>
              <option>Gasto de personal</option>
              <option>Gasto de empresa</option>
            </Select>
          </Field>
        )}

        <Field label="Notas"><TextInput placeholder="Opcional" value={form.notas} onChange={e => setForm({ ...form, notas: e.target.value })} /></Field>
        <PrimaryButton full onClick={addTx}>Agregar movimiento</PrimaryButton>
      </div>

      <SectionTitle>Historial</SectionTitle>
      {sorted.length === 0
        ? <p className="text-sm px-1" style={{ color: C.inkSoft }}>Sin movimientos registrados.</p>
        : sorted.map(t => (
          <div key={t.id} className="rounded-2xl p-3.5 mb-2.5 flex items-center gap-3" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
            <div className="flex-1 min-w-0">
              <p className="font-medium truncate" style={{ color: C.ink }}>{t.concepto}</p>
              <p className="text-xs truncate" style={{ color: C.inkSoft }}>{fmtDate(t.fecha)} · {t.medioPago || 'Efectivo'}{t.categoria ? ` · ${t.categoria}` : ''}{t.notas ? ` · ${t.notas}` : ''}</p>
            </div>
            <p className="font-semibold flex-shrink-0" style={{ color: t.tipo === 'ingreso' ? C.sage : C.brick }}>{t.tipo === 'ingreso' ? '+' : '-'}{fmtCOP(t.monto)}</p>
            <button onClick={() => removeTx(t.id)} className="w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0" style={{ background: C.line }}><X size={13} /></button>
          </div>
        ))}
    </div>
  );
}

function FinanzasGastosFijos({ gastosFijos, onChange, lists, onListsChange }) {
  const [form, setForm] = useState({ nombre: '', monto: '', frecuencia: 'Mensual', fecha: new Date().toISOString().slice(0, 10), medioPago: 'Efectivo', notas: '' });
  const [addingCuenta, setAddingCuenta] = useState(false);
  const [nuevaCuenta, setNuevaCuenta] = useState('');
  const cuentas = (lists.cuentas && lists.cuentas.length) ? lists.cuentas : ['Efectivo'];

  function addCuenta() {
    const v = nuevaCuenta.trim();
    if (!v) return;
    if (!cuentas.includes(v)) onListsChange({ ...lists, cuentas: [...cuentas, v] });
    setForm({ ...form, medioPago: v });
    setNuevaCuenta('');
    setAddingCuenta(false);
  }
  function addGasto() {
    if (!form.nombre.trim() || !form.monto) return;
    onChange([...gastosFijos, { id: uid(), ...form, monto: Number(form.monto) || 0, activo: true }]);
    setForm({ nombre: '', monto: '', frecuencia: 'Mensual', fecha: new Date().toISOString().slice(0, 10), medioPago: form.medioPago, notas: '' });
  }
  function toggleActivo(id) { onChange(gastosFijos.map(g => g.id === id ? { ...g, activo: !g.activo } : g)); }
  function removeGasto(id) { onChange(gastosFijos.filter(g => g.id !== id)); }

  const totalMensual = gastosFijos.filter(g => g.activo !== false).reduce((s, g) => s + gastoMensualizado(g), 0);

  return (
    <div className="pb-6">
      <StatCard label="Total gastos fijos / mes" value={fmtCOP(totalMensual)} accent={C.brick} />

      <SectionTitle>Nuevo gasto fijo</SectionTitle>
      <div className="rounded-2xl p-4 mb-5" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
        <Field label="Nombre"><TextInput placeholder="Ej. Arriendo del taller" value={form.nombre} onChange={e => setForm({ ...form, nombre: e.target.value })} /></Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Monto"><TextInput type="number" value={form.monto} onChange={e => setForm({ ...form, monto: e.target.value })} /></Field>
          <Field label="Frecuencia">
            <Select value={form.frecuencia} onChange={e => setForm({ ...form, frecuencia: e.target.value })}>
              <option>Mensual</option>
              <option>Semanal</option>
              <option>Anual</option>
              <option>Único</option>
            </Select>
          </Field>
        </div>
        {form.frecuencia === 'Único' && (
          <Field label="Fecha"><TextInput type="date" value={form.fecha} onChange={e => setForm({ ...form, fecha: e.target.value })} /></Field>
        )}
        <Field label="Medio de pago">
          {!addingCuenta ? (
            <div className="flex gap-2">
              <div className="flex-1">
                <Select value={form.medioPago} onChange={e => setForm({ ...form, medioPago: e.target.value })}>
                  {cuentas.map(c => <option key={c}>{c}</option>)}
                </Select>
              </div>
              <button onClick={() => setAddingCuenta(true)} className="w-11 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: C.line }}><Plus size={16} /></button>
            </div>
          ) : (
            <div className="flex gap-2">
              <div className="flex-1"><TextInput placeholder="Ej. Bancolombia Ahorros" value={nuevaCuenta} onChange={e => setNuevaCuenta(e.target.value)} onKeyDown={e => e.key === 'Enter' && addCuenta()} /></div>
              <button onClick={addCuenta} className="w-11 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: C.wine }}><Check size={16} color="#fff" /></button>
            </div>
          )}
        </Field>
        <Field label="Notas"><TextInput placeholder="Opcional" value={form.notas} onChange={e => setForm({ ...form, notas: e.target.value })} /></Field>
        <PrimaryButton full onClick={addGasto}>Agregar gasto fijo</PrimaryButton>
      </div>

      <SectionTitle>Tus gastos fijos</SectionTitle>
      {gastosFijos.length === 0
        ? <p className="text-sm px-1" style={{ color: C.inkSoft }}>Sin gastos fijos registrados.</p>
        : gastosFijos.map(g => (
          <div key={g.id} className="rounded-2xl p-3.5 mb-2.5" style={{ background: C.paper, border: `1px solid ${C.line}`, opacity: g.activo === false ? 0.5 : 1 }}>
            <div className="flex items-center justify-between mb-1">
              <p className="font-medium" style={{ color: C.ink }}>{g.nombre}</p>
              <button onClick={() => removeGasto(g.id)} className="w-7 h-7 rounded-full flex items-center justify-center" style={{ background: C.line }}><X size={13} /></button>
            </div>
            <div className="flex items-center justify-between text-sm">
              <span style={{ color: C.inkSoft }}>{g.frecuencia}</span>
              <span className="font-semibold" style={{ color: C.ink }}>{fmtCOP(g.monto)}</span>
            </div>
            <button onClick={() => toggleActivo(g.id)} className="text-xs mt-2" style={{ color: C.wine }}>{g.activo === false ? 'Reactivar' : 'Marcar como inactivo'}</button>
          </div>
        ))}
    </div>
  );
}

function FinanzasCartera({ orders, clients, onOpenOrder, filtro }) {
  const hoy = new Date().toISOString().slice(0, 10);
  const pendientesOrders = orders.filter(o => (Number(o.precio) || 0) - (Number(o.abono) || 0) > 0);
  const filtered = filtro === 'morosos' ? pendientesOrders.filter(o => o.fechaEntrega && o.fechaEntrega < hoy) : pendientesOrders;

  const porCliente = {};
  filtered.forEach(o => {
    const cid = o.clientId || 'sin-cliente';
    if (!porCliente[cid]) porCliente[cid] = { clientId: cid, total: 0, pedidos: [] };
    porCliente[cid].total += (Number(o.precio) || 0) - (Number(o.abono) || 0);
    porCliente[cid].pedidos.push(o);
  });
  const grupos = Object.values(porCliente).sort((a, b) => b.total - a.total);
  const totalCartera = grupos.reduce((s, g) => s + g.total, 0);

  return (
    <div className="pb-6">
      <StatCard label={filtro === 'morosos' ? 'Total en mora' : 'Total en cartera'} value={fmtCOP(totalCartera)} accent={C.brick} />
      <SectionTitle>{filtro === 'morosos' ? 'Clientas morosas' : 'Cartera por cliente'}</SectionTitle>
      {grupos.length === 0
        ? <p className="text-sm px-1" style={{ color: C.inkSoft }}>{filtro === 'morosos' ? 'No hay pagos en mora 🎉' : 'No hay cartera pendiente 🎉'}</p>
        : grupos.map(g => {
          const client = clients.find(c => c.id === g.clientId);
          return (
            <div key={g.clientId} className="rounded-2xl p-3.5 mb-2.5" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
              <div className="flex items-center justify-between mb-2">
                <p className="font-medium" style={{ color: C.ink }}>{client?.nombre || 'Sin cliente'}</p>
                <p className="font-semibold" style={{ color: C.brick }}>{fmtCOP(g.total)}</p>
              </div>
              {g.pedidos.map(o => {
                const late = o.fechaEntrega && o.fechaEntrega < hoy;
                return (
                  <button key={o.id} onClick={() => onOpenOrder(o)} className="w-full text-left flex items-center justify-between py-1.5 border-t" style={{ borderColor: C.line }}>
                    <span className="text-xs truncate" style={{ color: C.inkSoft }}>{o.codigo} · {o.prenda}</span>
                    <span className="text-xs flex-shrink-0" style={{ color: late ? C.brick : C.inkSoft }}>{late ? 'Atrasado' : fmtDate(o.fechaEntrega)}</span>
                  </button>
                );
              })}
            </div>
          );
        })}
    </div>
  );
}

function FinanzasHoy({ orders, transactions }) {
  const hoy = new Date().toISOString().slice(0, 10);
  const txHoy = (transactions || []).filter(t => t.fecha === hoy);
  const pedidosHoy = orders.filter(o => (o.createdAt || '').slice(0, 10) === hoy);
  const ingresosHoy = txHoy.filter(t => t.tipo === 'ingreso').reduce((s, t) => s + (Number(t.monto) || 0), 0);
  const egresosHoy = txHoy.filter(t => t.tipo === 'egreso').reduce((s, t) => s + (Number(t.monto) || 0), 0);
  const ventasHoy = pedidosHoy.reduce((s, o) => s + (Number(o.precio) || 0), 0);

  return (
    <div className="pb-6">
      <p className="text-sm mb-4" style={{ color: C.inkSoft }}>{fmtDate(hoy)}</p>
      <div className="grid grid-cols-2 gap-3 mb-5">
        <StatCard label="Pedidos nuevos hoy" value={pedidosHoy.length} />
        <StatCard label="Ventas de hoy" value={fmtCOP(ventasHoy)} small />
        <StatCard label="Ingresos manuales" value={fmtCOP(ingresosHoy)} small accent={C.sage} />
        <StatCard label="Egresos manuales" value={fmtCOP(egresosHoy)} small accent={C.brick} />
      </div>

      {pedidosHoy.length > 0 && (
        <>
          <SectionTitle>Pedidos creados hoy</SectionTitle>
          {pedidosHoy.map(o => (
            <div key={o.id} className="rounded-2xl p-3.5 mb-2.5 flex items-center justify-between" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
              <p className="text-sm truncate" style={{ color: C.ink }}>{o.codigo} · {o.prenda}</p>
              <p className="text-sm font-semibold flex-shrink-0" style={{ color: C.ink }}>{fmtCOP(o.precio)}</p>
            </div>
          ))}
        </>
      )}

      <SectionTitle>Movimientos manuales de hoy</SectionTitle>
      {txHoy.length === 0
        ? <p className="text-sm px-1" style={{ color: C.inkSoft }}>Sin movimientos manuales hoy.</p>
        : txHoy.map(t => (
          <div key={t.id} className="rounded-2xl p-3.5 mb-2.5 flex items-center justify-between" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
            <p className="text-sm truncate" style={{ color: C.ink }}>{t.concepto}</p>
            <p className="text-sm font-semibold flex-shrink-0" style={{ color: t.tipo === 'ingreso' ? C.sage : C.brick }}>{t.tipo === 'ingreso' ? '+' : '-'}{fmtCOP(t.monto)}</p>
          </div>
        ))}
    </div>
  );
}

function FinanzasAhorros({ ahorros, onChange }) {
  const [form, setForm] = useState({ fecha: new Date().toISOString().slice(0, 10), tipo: 'deposito', monto: '', nota: '' });

  function addMov() {
    if (!form.monto) return;
    onChange([...ahorros, { id: uid(), ...form, monto: Number(form.monto) || 0 }]);
    setForm({ fecha: new Date().toISOString().slice(0, 10), tipo: 'deposito', monto: '', nota: '' });
  }
  function removeMov(id) { onChange(ahorros.filter(a => a.id !== id)); }

  const total = ahorros.reduce((s, a) => s + (a.tipo === 'deposito' ? (Number(a.monto) || 0) : -(Number(a.monto) || 0)), 0);
  const sorted = ahorros.slice().sort((a, b) => (b.fecha || '').localeCompare(a.fecha || ''));

  return (
    <div className="pb-6">
      <StatCard label="Total en ahorros" value={fmtCOP(total)} accent={C.sage} />

      <SectionTitle>Nuevo movimiento de ahorro</SectionTitle>
      <div className="rounded-2xl p-4 mb-5" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
        <div className="flex gap-2 mb-3">
          <button onClick={() => setForm({ ...form, tipo: 'deposito' })} className="flex-1 rounded-xl py-2 text-sm font-medium" style={{ background: form.tipo === 'deposito' ? C.sage : C.line, color: form.tipo === 'deposito' ? '#fff' : C.ink }}>Depósito</button>
          <button onClick={() => setForm({ ...form, tipo: 'retiro' })} className="flex-1 rounded-xl py-2 text-sm font-medium" style={{ background: form.tipo === 'retiro' ? C.brick : C.line, color: form.tipo === 'retiro' ? '#fff' : C.ink }}>Retiro</button>
        </div>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Monto"><TextInput type="number" value={form.monto} onChange={e => setForm({ ...form, monto: e.target.value })} /></Field>
          <Field label="Fecha"><TextInput type="date" value={form.fecha} onChange={e => setForm({ ...form, fecha: e.target.value })} /></Field>
        </div>
        <Field label="Nota"><TextInput placeholder="Opcional" value={form.nota} onChange={e => setForm({ ...form, nota: e.target.value })} /></Field>
        <PrimaryButton full onClick={addMov}>Agregar</PrimaryButton>
      </div>

      <SectionTitle>Historial de ahorros</SectionTitle>
      {sorted.length === 0
        ? <p className="text-sm px-1" style={{ color: C.inkSoft }}>Aún no has registrado ahorros.</p>
        : sorted.map(a => (
          <div key={a.id} className="rounded-2xl p-3.5 mb-2.5 flex items-center gap-3" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
            <div className="flex-1 min-w-0">
              <p className="font-medium truncate" style={{ color: C.ink }}>{a.tipo === 'deposito' ? 'Depósito' : 'Retiro'}{a.nota ? ` · ${a.nota}` : ''}</p>
              <p className="text-xs" style={{ color: C.inkSoft }}>{fmtDate(a.fecha)}</p>
            </div>
            <p className="font-semibold flex-shrink-0" style={{ color: a.tipo === 'deposito' ? C.sage : C.brick }}>{a.tipo === 'deposito' ? '+' : '-'}{fmtCOP(a.monto)}</p>
            <button onClick={() => removeMov(a.id)} className="w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0" style={{ background: C.line }}><X size={13} /></button>
          </div>
        ))}
    </div>
  );
}

function Finanzas({ orders, clients, transactions, onTransactionsChange, gastosFijos, onGastosFijosChange, onOpenOrder, lists, onListsChange, ahorros, onAhorrosChange }) {
  const [sub, setSub] = useState('resumen');
  const tabs = [
    { key: 'resumen', label: 'Resumen' },
    { key: 'mes', label: 'Resumen del mes' },
    { key: 'movimientos', label: 'Ingresos/Egresos' },
    { key: 'fijos', label: 'Gastos fijos' },
    { key: 'ahorros', label: 'Ahorros' },
    { key: 'cartera', label: 'Cartera' },
    { key: 'dia', label: 'Hoy' },
    { key: 'morosos', label: 'Morosos' },
  ];
  return (
    <div>
      <div className="flex gap-2 mb-4 overflow-x-auto pb-1">
        {tabs.map(t => (
          <button key={t.key} onClick={() => setSub(t.key)} className="flex-shrink-0 rounded-full px-3 py-1.5 text-xs font-medium" style={{ background: sub === t.key ? C.wine : C.line, color: sub === t.key ? '#fff' : C.ink }}>
            {t.label}
          </button>
        ))}
      </div>
      {sub === 'resumen' && <FinanzasResumen orders={orders} gastosFijos={gastosFijos} transactions={transactions} />}
      {sub === 'mes' && <FinanzasResumenMensual orders={orders} transactions={transactions} gastosFijos={gastosFijos} />}
      {sub === 'movimientos' && <FinanzasMovimientos transactions={transactions} onChange={onTransactionsChange} lists={lists} onListsChange={onListsChange} />}
      {sub === 'fijos' && <FinanzasGastosFijos gastosFijos={gastosFijos} onChange={onGastosFijosChange} lists={lists} onListsChange={onListsChange} />}
      {sub === 'ahorros' && <FinanzasAhorros ahorros={ahorros} onChange={onAhorrosChange} />}
      {sub === 'cartera' && <FinanzasCartera orders={orders} clients={clients} onOpenOrder={onOpenOrder} filtro="todos" />}
      {sub === 'dia' && <FinanzasHoy orders={orders} transactions={transactions} />}
      {sub === 'morosos' && <FinanzasCartera orders={orders} clients={clients} onOpenOrder={onOpenOrder} filtro="morosos" />}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Candado de contraseña adicional (Finanzas y Listas)                 */
/* ------------------------------------------------------------------ */
function PasswordGate({ password, title, children }) {
  const [unlocked, setUnlocked] = useState(false);
  const [pw, setPw] = useState('');
  const [err, setErr] = useState('');

  if (unlocked) return children;

  function tryUnlock() {
    if (pw === password) { setUnlocked(true); setErr(''); }
    else setErr('Contraseña incorrecta');
  }

  return (
    <div className="pb-6">
      <div className="rounded-2xl p-5 text-center" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
        <div className="w-12 h-12 rounded-full mx-auto mb-3 flex items-center justify-center" style={{ background: C.line }}>
          <Lock size={20} style={{ color: C.wine }} />
        </div>
        <p className="font-medium mb-1" style={{ color: C.ink }}>{title}</p>
        <p className="text-sm mb-4" style={{ color: C.inkSoft }}>Esta sección tiene una contraseña adicional.</p>
        <TextInput type="password" placeholder="Contraseña" value={pw} onChange={e => setPw(e.target.value)} onKeyDown={e => e.key === 'Enter' && tryUnlock()} />
        {err && <p className="text-sm mt-2" style={{ color: C.brick }}>{err}</p>}
        <div className="mt-3">
          <PrimaryButton full onClick={tryUnlock}>Entrar</PrimaryButton>
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Telas para personalizados (catálogo público)                        */
/* ------------------------------------------------------------------ */
function TelaForm({ initial, onSave, onCancel, onDelete }) {
  const [f, setF] = useState(initial ? { prendas: [], ...initial } : { nombre: '', descripcionTextura: '', conoceMas: '', precioPorMetro: '', imagenes: [], prendas: [] });
  const [err, setErr] = useState('');
  const fileRef = useRef(null);

  async function handleAddPhoto(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const dataUrl = await resizeImage(file);
      setF(prev => ({ ...prev, imagenes: [...(prev.imagenes || []), dataUrl] }));
    } catch { /* ignore */ }
    e.target.value = '';
  }
  function removePhoto(i) { setF(prev => ({ ...prev, imagenes: prev.imagenes.filter((_, idx) => idx !== i) })); }

  function addPrenda() { setF(prev => ({ ...prev, prendas: [...(prev.prendas || []), { id: uid(), nombre: '', precio: '' }] })); }
  function updatePrenda(id, patch) { setF(prev => ({ ...prev, prendas: prev.prendas.map(p => p.id === id ? { ...p, ...patch } : p) })); }
  function removePrenda(id) { setF(prev => ({ ...prev, prendas: prev.prendas.filter(p => p.id !== id) })); }

  function submit() {
    if (!f.nombre.trim()) { setErr('Escribe el nombre de la tela'); return; }
    const prendasLimpias = (f.prendas || []).filter(p => p.nombre.trim() && p.precio).map(p => ({ ...p, precio: Number(p.precio) || 0 }));
    onSave({ ...f, precioPorMetro: Number(f.precioPorMetro) || 0, prendas: prendasLimpias });
  }

  return (
    <div>
      <Field label="Nombre" required><TextInput placeholder="Ej. Encaje francés" value={f.nombre} onChange={e => setF({ ...f, nombre: e.target.value })} /></Field>
      <Field label="Textura (resumen corto)"><TextInput placeholder="Ej. Suave y semitransparente" value={f.descripcionTextura} onChange={e => setF({ ...f, descripcionTextura: e.target.value })} /></Field>
      <Field label="Conoce más de esta tela"><TextArea placeholder="Composición, por qué se caracteriza, cuidados, caída…" value={f.conoceMas} onChange={e => setF({ ...f, conoceMas: e.target.value })} /></Field>
      <Field label="Precio de referencia por metro (opcional)"><TextInput type="number" value={f.precioPorMetro} onChange={e => setF({ ...f, precioPorMetro: e.target.value })} /></Field>
      <Field label="Fotos de la tela">
        <input ref={fileRef} type="file" accept="image/*" onChange={handleAddPhoto} className="hidden" />
        <div className="flex flex-wrap gap-2 mb-2">
          {(f.imagenes || []).map((foto, i) => (
            <div key={i} className="relative w-16 h-16 rounded-lg overflow-hidden flex-shrink-0" style={{ border: `1px solid ${C.line}` }}>
              <img src={foto} className="w-full h-full object-cover" />
              <button onClick={() => removePhoto(i)} className="absolute top-0.5 right-0.5 w-5 h-5 rounded-full flex items-center justify-center" style={{ background: 'rgba(0,0,0,0.6)' }}>
                <X size={11} color="#fff" />
              </button>
            </div>
          ))}
        </div>
        <button onClick={() => fileRef.current?.click()} className="w-full rounded-xl py-3 flex items-center justify-center gap-2 border" style={{ borderColor: C.line, borderStyle: 'dashed' }}>
          <Camera size={18} style={{ color: C.inkSoft }} />
          <span className="text-sm" style={{ color: C.inkSoft }}>Agregar foto</span>
        </button>
      </Field>

      <Field label="¿Qué se puede hacer con esta tela?">
        <p className="text-xs mb-2" style={{ color: C.inkSoft }}>Agrega cada prenda con el precio que le pones según cuánta tela lleva (ej. Vestido midi, Vestido corto, Blusa, Falda…).</p>
        {(f.prendas || []).map(p => (
          <div key={p.id} className="flex gap-2 mb-2">
            <div className="flex-1"><TextInput placeholder="Ej. Vestido midi" value={p.nombre} onChange={e => updatePrenda(p.id, { nombre: e.target.value })} /></div>
            <div className="w-28"><TextInput type="number" placeholder="Precio" value={p.precio} onChange={e => updatePrenda(p.id, { precio: e.target.value })} /></div>
            <button onClick={() => removePrenda(p.id)} className="w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0" style={{ background: C.line }}><X size={14} /></button>
          </div>
        ))}
        <button onClick={addPrenda} className="text-sm font-medium" style={{ color: C.wine }}>+ Agregar prenda</button>
      </Field>

      {err && <p className="text-sm mb-2 mt-3" style={{ color: C.brick }}>{err}</p>}
      <div className="flex gap-2 mt-4">
        {initial && <button onClick={() => onDelete(initial)} className="rounded-xl py-2.5 px-4" style={{ color: C.brick }}><Trash2 size={18} /></button>}
        <GhostButton full onClick={onCancel}>Cancelar</GhostButton>
        <PrimaryButton full onClick={submit}>Guardar</PrimaryButton>
      </div>
    </div>
  );
}

function TelasCatalogo({ telas, onChange }) {
  const [modal, setModal] = useState(null); // { mode, tela }

  function saveTela(t) {
    onChange(modal.mode === 'edit' ? telas.map(x => x.id === t.id ? t : x) : [...telas, { id: uid(), ...t }]);
    setModal(null);
  }
  function deleteTela(t) { onChange(telas.filter(x => x.id !== t.id)); setModal(null); }

  return (
    <div className="pb-6">
      <p className="text-xs mb-3" style={{ color: C.inkSoft }}>Estas telas se muestran en el catálogo público, en la sección de Personalizados, con las prendas y precios que definas para cada una.</p>
      {telas.length === 0
        ? <EmptyState icon={Layers} title="Sin telas registradas" subtitle="Agrega tu primera tela con el botón de abajo" />
        : telas.map(t => (
          <button key={t.id} onClick={() => setModal({ mode: 'edit', tela: t })} className="w-full text-left rounded-2xl p-3.5 flex gap-3 mb-2.5" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
            <div className="w-14 h-14 rounded-xl flex-shrink-0 overflow-hidden flex items-center justify-center" style={{ background: C.cream }}>
              {t.imagenes?.[0] ? <img src={t.imagenes[0]} className="w-full h-full object-cover" /> : <ImageOff size={16} style={{ color: C.inkSoft }} />}
            </div>
            <div className="flex-1 min-w-0">
              <p className="font-medium truncate" style={{ color: C.ink }}>{t.nombre}</p>
              <p className="text-xs truncate mb-1" style={{ color: C.inkSoft }}>{t.descripcionTextura || 'Sin descripción'}</p>
              <Badge bg={C.line} fg={C.ink}>{(t.prendas || []).length} prenda{(t.prendas || []).length !== 1 ? 's' : ''} configurada{(t.prendas || []).length !== 1 ? 's' : ''}</Badge>
            </div>
          </button>
        ))}
      <button onClick={() => setModal({ mode: 'new', tela: null })} className="w-full rounded-xl py-3 font-medium mt-1" style={{ background: C.wine, color: '#fff' }}>+ Nueva tela</button>

      {modal && (
        <Sheet title={modal.mode === 'edit' ? 'Editar tela' : 'Nueva tela'} onClose={() => setModal(null)}>
          <TelaForm initial={modal.tela} onSave={saveTela} onCancel={() => setModal(null)} onDelete={deleteTela} />
        </Sheet>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Inspiración (fotos + tableros de Pinterest)                         */
/* ------------------------------------------------------------------ */
function InspiracionForm({ initial, onSave, onCancel, onDelete }) {
  const [f, setF] = useState(initial || { titulo: '', nota: '', imagen: '' });
  const [err, setErr] = useState('');
  const fileRef = useRef(null);

  async function handlePhoto(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    try { const dataUrl = await resizeImage(file); setF(prev => ({ ...prev, imagen: dataUrl })); } catch { /* ignore */ }
  }
  function submit() {
    if (!f.imagen) { setErr('Agrega una foto'); return; }
    onSave(f);
  }

  return (
    <div>
      <Field label="Foto" required>
        <input ref={fileRef} type="file" accept="image/*" onChange={handlePhoto} className="hidden" />
        <button onClick={() => fileRef.current?.click()} className="w-full rounded-xl py-3 flex items-center justify-center gap-2 border" style={{ borderColor: C.line, borderStyle: 'dashed' }}>
          {f.imagen ? <img src={f.imagen} className="w-14 h-14 rounded-lg object-cover" /> : <Camera size={18} style={{ color: C.inkSoft }} />}
          <span className="text-sm" style={{ color: C.inkSoft }}>{f.imagen ? 'Cambiar foto' : 'Agregar foto'}</span>
        </button>
      </Field>
      <Field label="Título (opcional)"><TextInput placeholder="Ej. Vestido midi romántico" value={f.titulo} onChange={e => setF({ ...f, titulo: e.target.value })} /></Field>
      <Field label="Nota (opcional)"><TextArea placeholder="Detalles o inspiración detrás de este diseño" value={f.nota} onChange={e => setF({ ...f, nota: e.target.value })} /></Field>
      {err && <p className="text-sm mb-2" style={{ color: C.brick }}>{err}</p>}
      <div className="flex gap-2 mt-4">
        {initial && <button onClick={() => onDelete(initial)} className="rounded-xl py-2.5 px-4" style={{ color: C.brick }}><Trash2 size={18} /></button>}
        <GhostButton full onClick={onCancel}>Cancelar</GhostButton>
        <PrimaryButton full onClick={submit}>Guardar</PrimaryButton>
      </div>
    </div>
  );
}

function PinterestForm({ initial, onSave, onCancel, onDelete }) {
  const [f, setF] = useState(initial || { nombre: '', url: '' });
  const [err, setErr] = useState('');
  function submit() {
    if (!f.nombre.trim()) { setErr('Escribe un nombre para el tablero'); return; }
    if (!/^https?:\/\//i.test(f.url.trim())) { setErr('Pega el enlace completo del tablero (empieza con https://)'); return; }
    onSave(f);
  }
  return (
    <div>
      <Field label="Nombre del tablero" required><TextInput placeholder="Ej. Vestidos boho" value={f.nombre} onChange={e => setF({ ...f, nombre: e.target.value })} /></Field>
      <Field label="Enlace de Pinterest" required><TextInput placeholder="https://pinterest.com/..." value={f.url} onChange={e => setF({ ...f, url: e.target.value })} /></Field>
      {err && <p className="text-sm mb-2" style={{ color: C.brick }}>{err}</p>}
      <div className="flex gap-2 mt-4">
        {initial && <button onClick={() => onDelete(initial)} className="rounded-xl py-2.5 px-4" style={{ color: C.brick }}><Trash2 size={18} /></button>}
        <GhostButton full onClick={onCancel}>Cancelar</GhostButton>
        <PrimaryButton full onClick={submit}>Guardar</PrimaryButton>
      </div>
    </div>
  );
}

function Inspiracion({ fotos, onFotosChange, tableros, onTablerosChange }) {
  const [fotoModal, setFotoModal] = useState(null);
  const [pinModal, setPinModal] = useState(null);

  function saveFoto(f) {
    onFotosChange(fotoModal.mode === 'edit' ? fotos.map(x => x.id === f.id ? f : x) : [...fotos, { id: uid(), ...f }]);
    setFotoModal(null);
  }
  function deleteFoto(f) { onFotosChange(fotos.filter(x => x.id !== f.id)); setFotoModal(null); }
  function savePin(p) {
    onTablerosChange(pinModal.mode === 'edit' ? tableros.map(x => x.id === p.id ? p : x) : [...tableros, { id: uid(), ...p }]);
    setPinModal(null);
  }
  function deletePin(p) { onTablerosChange(tableros.filter(x => x.id !== p.id)); setPinModal(null); }

  return (
    <div className="pb-6">
      <SectionTitle>Fotos de inspiración</SectionTitle>
      <p className="text-xs mb-3" style={{ color: C.inkSoft }}>Aparecen en el catálogo público, en la pestaña Inspiración.</p>
      <div className="grid grid-cols-2 gap-3 mb-3">
        {fotos.map(f => (
          <button key={f.id} onClick={() => setFotoModal({ mode: 'edit', foto: f })} className="rounded-2xl overflow-hidden text-left" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
            <div className="w-full aspect-square" style={{ background: C.cream }}>
              <img src={f.imagen} className="w-full h-full object-cover" />
            </div>
            {f.titulo && <p className="text-xs font-medium px-2 py-1.5 truncate" style={{ color: C.ink }}>{f.titulo}</p>}
          </button>
        ))}
      </div>
      <button onClick={() => setFotoModal({ mode: 'new', foto: null })} className="w-full rounded-xl py-3 font-medium mb-6" style={{ background: C.wine, color: '#fff' }}>+ Nueva foto de inspiración</button>

      <SectionTitle>Tableros de Pinterest</SectionTitle>
      <p className="text-xs mb-3" style={{ color: C.inkSoft }}>Agrupa tus tableros por estilo (ej. "Boda", "Boho", "Elegante").</p>
      {tableros.length === 0
        ? <p className="text-sm px-1 mb-3" style={{ color: C.inkSoft }}>Sin tableros agregados.</p>
        : tableros.map(t => (
          <button key={t.id} onClick={() => setPinModal({ mode: 'edit', tablero: t })} className="w-full text-left rounded-2xl p-3.5 mb-2.5" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
            <p className="font-medium" style={{ color: C.ink }}>{t.nombre}</p>
            <p className="text-xs truncate" style={{ color: C.inkSoft }}>{t.url}</p>
          </button>
        ))}
      <button onClick={() => setPinModal({ mode: 'new', tablero: null })} className="w-full rounded-xl py-3 font-medium" style={{ background: C.wine, color: '#fff' }}>+ Nuevo tablero</button>

      {fotoModal && (
        <Sheet title={fotoModal.mode === 'edit' ? 'Editar foto' : 'Nueva foto de inspiración'} onClose={() => setFotoModal(null)}>
          <InspiracionForm initial={fotoModal.foto} onSave={saveFoto} onCancel={() => setFotoModal(null)} onDelete={deleteFoto} />
        </Sheet>
      )}
      {pinModal && (
        <Sheet title={pinModal.mode === 'edit' ? 'Editar tablero' : 'Nuevo tablero'} onClose={() => setPinModal(null)}>
          <PinterestForm initial={pinModal.tablero} onSave={savePin} onCancel={() => setPinModal(null)} onDelete={deletePin} />
        </Sheet>
      )}
    </div>
  );
}

