function PasswordChanger({ onChangePassword }) {
  const [current, setCurrent] = useState('');
  const [next, setNext] = useState('');
  const [confirm, setConfirm] = useState('');
  const [msg, setMsg] = useState('');
  const [ok, setOk] = useState(false);

  async function submit() {
    if (!next || next.length < 4) { setOk(false); setMsg('La nueva contraseña debe tener al menos 4 caracteres'); return; }
    if (next !== confirm) { setOk(false); setMsg('Las contraseñas nuevas no coinciden'); return; }
    const success = await onChangePassword(current, next);
    if (success) {
      setOk(true); setMsg('Contraseña actualizada'); setCurrent(''); setNext(''); setConfirm('');
    } else {
      setOk(false); setMsg('La contraseña actual no es correcta');
    }
  }

  return (
    <div className="rounded-2xl p-4" style={{ background: C.paper, border: `1px solid ${C.line}` }}>
      <Field label="Contraseña actual">
        <TextInput type="password" value={current} onChange={e => setCurrent(e.target.value)} />
      </Field>
      <Field label="Nueva contraseña">
        <TextInput type="password" value={next} onChange={e => setNext(e.target.value)} />
      </Field>
      <Field label="Confirmar nueva contraseña">
        <TextInput type="password" value={confirm} onChange={e => setConfirm(e.target.value)} />
      </Field>
      {msg && <p className="text-sm mb-2" style={{ color: ok ? C.sage : C.brick }}>{msg}</p>}
      <PrimaryButton full onClick={submit}>Actualizar contraseña</PrimaryButton>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Fondo de partículas rosadas (sigue el cursor)                      */
/* ------------------------------------------------------------------ */
function ParticlesBackground() {
  const canvasRef = useRef(null);
  const mouseRef = useRef({ x: null, y: null, active: false });
  const particlesRef = useRef([]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    let width = 0, height = 0, animationId;

    const PALETTE = ['#FFFFFF', '#FFFFFF', '#FFF6FB', '#FDE3F2', '#F6C9E6', '#FFD9EE'];

    function resize() {
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      canvas.style.width = width + 'px';
      canvas.style.height = height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const density = window.innerWidth < 640 ? 9000 : 7000;
      const count = Math.max(60, Math.min(220, Math.floor((width * height) / density)));
      particlesRef.current = Array.from({ length: count }, () => ({
        x: Math.random() * width,
        y: Math.random() * height,
        r: Math.random() * 1.8 + 0.5,
        vx: (Math.random() - 0.5) * 0.12,
        vy: (Math.random() - 0.5) * 0.12,
        color: PALETTE[Math.floor(Math.random() * PALETTE.length)],
        opacity: Math.random() * 0.5 + 0.35,
        twinkleSpeed: Math.random() * 0.02 + 0.006,
        twinklePhase: Math.random() * Math.PI * 2,
        glow: Math.random() < 0.24,
      }));
    }
    resize();
    window.addEventListener('resize', resize);

    function handleMove(e) {
      const x = e.touches ? e.touches[0].clientX : e.clientX;
      const y = e.touches ? e.touches[0].clientY : e.clientY;
      mouseRef.current = { x, y, active: true };
    }
    function handleLeave() { mouseRef.current.active = false; }
    window.addEventListener('mousemove', handleMove, { passive: true });
    window.addEventListener('touchmove', handleMove, { passive: true });
    window.addEventListener('mouseleave', handleLeave);

    function animate() {
      ctx.clearRect(0, 0, width, height);
      const mouse = mouseRef.current;
      const particles = particlesRef.current;

      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        if (p.x < -10) p.x = width + 10; else if (p.x > width + 10) p.x = -10;
        if (p.y < -10) p.y = height + 10; else if (p.y > height + 10) p.y = -10;

        if (mouse.active) {
          const dx = mouse.x - p.x, dy = mouse.y - p.y;
          const dist = Math.sqrt(dx * dx + dy * dy) || 1;
          const radius = 150;
          if (dist < radius) {
            const force = ((radius - dist) / radius) * 0.9;
            p.x -= (dx / dist) * force;
            p.y -= (dy / dist) * force;
          }
        }
      }

      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];
        p.twinklePhase += p.twinkleSpeed;
        const twinkle = 0.5 + 0.5 * Math.sin(p.twinklePhase);
        ctx.beginPath();
        ctx.globalAlpha = Math.min(1, p.opacity * (0.55 + 0.45 * twinkle));
        ctx.fillStyle = p.color;
        if (p.glow) {
          ctx.shadowColor = '#FFFFFF';
          ctx.shadowBlur = 10 + 6 * twinkle;
        } else {
          ctx.shadowBlur = 0;
        }
        ctx.arc(p.x, p.y, p.r * (p.glow ? (0.85 + 0.3 * twinkle) : 1), 0, Math.PI * 2);
        ctx.fill();
        // pequeño destello en cruz sobre las estrellas brillantes, sin líneas entre ellas
        if (p.glow && twinkle > 0.75) {
          const s = p.r * 3.2 * twinkle;
          ctx.globalAlpha = Math.min(1, (twinkle - 0.75) * 3);
          ctx.strokeStyle = '#FFFFFF';
          ctx.lineWidth = 0.6;
          ctx.beginPath();
          ctx.moveTo(p.x - s, p.y);
          ctx.lineTo(p.x + s, p.y);
          ctx.moveTo(p.x, p.y - s);
          ctx.lineTo(p.x, p.y + s);
          ctx.stroke();
        }
      }
      ctx.shadowBlur = 0;
      ctx.globalAlpha = 1;

      animationId = requestAnimationFrame(animate);
    }
    animate();

    return () => {
      cancelAnimationFrame(animationId);
      window.removeEventListener('resize', resize);
      window.removeEventListener('mousemove', handleMove);
      window.removeEventListener('touchmove', handleMove);
      window.removeEventListener('mouseleave', handleLeave);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className="fixed inset-0 pointer-events-none"
      style={{ zIndex: 0 }}
      aria-hidden="true"
    />
  );
}

/* ------------------------------------------------------------------ */
/*  App root                                                            */
/* ------------------------------------------------------------------ */
export default function App() {
  const [loading, setLoading] = useState(true);
  const [orders, setOrders] = useState([]);
  const [clients, setClients] = useState([]);
  const [lists, setLists] = useState(DEFAULT_LISTS);
  const [quotes, setQuotes] = useState([]);
  const [catalog, setCatalog] = useState(defaultCatalog());
  const [goals, setGoals] = useState([]);
  const [transactions, setTransactions] = useState([]);
  const [gastosFijos, setGastosFijos] = useState([]);
  const [ahorros, setAhorros] = useState([]);
  const [telasCatalogo, setTelasCatalogo] = useState([]);
  const [inspiracionFotos, setInspiracionFotos] = useState([]);
  const [pinterestTableros, setPinterestTableros] = useState([]);
  const [tab, setTab] = useState('inicio');
  const [masSub, setMasSub] = useState('pagos');
  const [sidebarOpen, setSidebarOpen] = useState(true);

  const [orderModal, setOrderModal] = useState(null); // { mode: 'new'|'edit', order }
  const [orderDetail, setOrderDetail] = useState(null);
  const [orderCostsModal, setOrderCostsModal] = useState(null); // order
  const [clientModal, setClientModal] = useState(null);
  const [clientDetail, setClientDetail] = useState(null);
  const [quoteModal, setQuoteModal] = useState(null); // { mode: 'new'|'edit', quote }
  const [saveError, setSaveError] = useState('');

  const [authPassword, setAuthPassword] = useState('kawa2026');
  const [advancedPassword, setAdvancedPassword] = useState('kawa2026fin');
  const [authed, setAuthed] = useState(false);
  const [authError, setAuthError] = useState('');

  useEffect(() => {
    (async () => {
      try {
        const [o, c, l, auth, qt, cat, gl, tx, gf, ah, tc, ifo, pin] = await Promise.all([
          window.storage.get('kawa-orders', true).catch(() => null),
          window.storage.get('kawa-clients', true).catch(() => null),
          window.storage.get('kawa-lists', true).catch(() => null),
          window.storage.get('kawa-auth', true).catch(() => null),
          window.storage.get('kawa-quotes', true).catch(() => null),
          window.storage.get('kawa-catalog', true).catch(() => null),
          window.storage.get('kawa-goals', true).catch(() => null),
          window.storage.get('kawa-transactions', true).catch(() => null),
          window.storage.get('kawa-gastosfijos', true).catch(() => null),
          window.storage.get('kawa-ahorros', true).catch(() => null),
          window.storage.get('kawa-telascatalogo', true).catch(() => null),
          window.storage.get('kawa-inspiracion', true).catch(() => null),
          window.storage.get('kawa-pinterest', true).catch(() => null),
        ]);
        if (o?.value) setOrders(JSON.parse(o.value));
        if (c?.value) setClients(JSON.parse(c.value));
        if (l?.value) {
          const savedLists = JSON.parse(l.value);
          const mergedCuentas = Array.from(new Set([...(savedLists.cuentas || []), ...DEFAULT_LISTS.cuentas]));
          setLists({ ...DEFAULT_LISTS, ...savedLists, cuentas: mergedCuentas });
        }
        if (qt?.value) setQuotes(JSON.parse(qt.value).map(normalizeQuote));
        if (cat?.value) setCatalog(JSON.parse(cat.value));
        if (gl?.value) setGoals(JSON.parse(gl.value));
        if (tx?.value) setTransactions(JSON.parse(tx.value));
        if (gf?.value) setGastosFijos(JSON.parse(gf.value));
        if (ah?.value) setAhorros(JSON.parse(ah.value));
        if (tc?.value) setTelasCatalogo(JSON.parse(tc.value));
        if (ifo?.value) setInspiracionFotos(JSON.parse(ifo.value));
        if (pin?.value) setPinterestTableros(JSON.parse(pin.value));
        if (auth?.value) {
          const parsedAuth = JSON.parse(auth.value);
          setAuthPassword(parsedAuth.password || 'kawa2026');
          setAdvancedPassword(parsedAuth.passwordAvanzada || 'kawa2026fin');
          if (!parsedAuth.passwordAvanzada) {
            await window.storage.set('kawa-auth', JSON.stringify({ password: parsedAuth.password || 'kawa2026', passwordAvanzada: 'kawa2026fin' }), true).catch(() => null);
          }
        } else {
          await window.storage.set('kawa-auth', JSON.stringify({ password: 'kawa2026', passwordAvanzada: 'kawa2026fin' }), true).catch(() => null);
        }
      } catch (e) {
        setSaveError('No se pudo cargar la información guardada.');
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  async function persist(key, value) {
    try {
      const res = await window.storage.set(key, JSON.stringify(value), true);
      if (!res) setSaveError('No se pudo guardar el cambio. Intenta de nuevo.');
      else setSaveError('');
    } catch {
      setSaveError('No se pudo guardar el cambio. Intenta de nuevo.');
    }
  }

  function saveOrders(next) { setOrders(next); persist('kawa-orders', next); }
  function saveClients(next) { setClients(next); persist('kawa-clients', next); }
  function saveLists(next) { setLists(next); persist('kawa-lists', next); }
  function saveQuotes(next) { setQuotes(next); persist('kawa-quotes', next); }
  function saveCatalog(next) { setCatalog(next); persist('kawa-catalog', next); }
  function saveGoals(next) { setGoals(next); persist('kawa-goals', next); }
  function saveTransactions(next) { setTransactions(next); persist('kawa-transactions', next); }
  function saveGastosFijos(next) { setGastosFijos(next); persist('kawa-gastosfijos', next); }
  function saveAhorros(next) { setAhorros(next); persist('kawa-ahorros', next); }
  function saveTelasCatalogo(next) { setTelasCatalogo(next); persist('kawa-telascatalogo', next); }
  function saveInspiracionFotos(next) { setInspiracionFotos(next); persist('kawa-inspiracion', next); }
  function savePinterestTableros(next) { setPinterestTableros(next); persist('kawa-pinterest', next); }
  function adjustStock(coleccionId, prendaId, delta) {
    if (!coleccionId || !prendaId) return;
    const next = {
      colecciones: catalog.colecciones.map(c => c.id !== coleccionId ? c : {
        ...c, prendas: c.prendas.map(p => p.id !== prendaId ? p : { ...p, disponible: Math.max(0, (Number(p.disponible) || 0) + delta) }),
      }),
    };
    saveCatalog(next);
  }

  function createClient(data) {
    const client = { id: uid(), codigo: nextCode(clients, 'codigo', 'KC', 0), nombre: data.nombre.trim(), telefono: data.telefono || '', instagram: data.instagram || '', createdAt: new Date().toISOString() };
    saveClients([...clients, client]);
    return client;
  }

  function handleSaveOrder(data) {
    if (orderModal?.mode === 'edit') {
      const old = orderModal.order;
      if (old.tipo === 'Catálogo' && old.prendaCatalogoId && (data.tipo !== 'Catálogo' || data.prendaCatalogoId !== old.prendaCatalogoId)) {
        adjustStock(old.coleccionId, old.prendaCatalogoId, 1);
      }
      if (data.tipo === 'Catálogo' && data.prendaCatalogoId && (old.tipo !== 'Catálogo' || old.prendaCatalogoId !== data.prendaCatalogoId)) {
        adjustStock(data.coleccionId, data.prendaCatalogoId, -1);
      }
      saveOrders(orders.map(o => o.id === old.id ? { ...old, ...data } : o));
    } else {
      if (data.tipo === 'Catálogo' && data.prendaCatalogoId) {
        adjustStock(data.coleccionId, data.prendaCatalogoId, -1);
      }
      saveOrders([...orders, { id: uid(), ...data, createdAt: new Date().toISOString() }]);
    }
    setOrderModal(null);
  }
  function handleDeleteOrder(order) {
    if (order.tipo === 'Catálogo' && order.prendaCatalogoId) {
      adjustStock(order.coleccionId, order.prendaCatalogoId, 1);
    }
    saveOrders(orders.filter(o => o.id !== order.id));
    setOrderModal(null);
    setOrderDetail(null);
  }
  function handleStageChange(order, etapa) {
    const updated = { ...order, etapa };
    saveOrders(orders.map(o => o.id === order.id ? updated : o));
    setOrderDetail(updated);
  }
  function handleSaveClient(data) {
    if (clientModal?.mode === 'edit') {
      saveClients(clients.map(c => c.id === clientModal.client.id ? { ...c, ...data } : c));
    } else {
      saveClients([...clients, { id: uid(), codigo: nextCode(clients, 'codigo', 'KC', 0), ...data, createdAt: new Date().toISOString() }]);
    }
    setClientModal(null);
  }
  function handleDeleteClient(client) {
    saveClients(clients.filter(c => c.id !== client.id));
    setClientModal(null);
    setClientDetail(null);
  }
  function updateClientMedidas(clientId, medidas) {
    saveClients(clients.map(c => c.id === clientId ? { ...c, medidas } : c));
  }

  function handleSaveQuote(q) {
    const exists = quotes.some(x => x.id === q.id);
    saveQuotes(exists ? quotes.map(x => x.id === q.id ? q : x) : [...quotes, q]);
    setQuoteModal(null);
  }
  function handleDeleteQuote(q) {
    saveQuotes(quotes.filter(x => x.id !== q.id));
    setQuoteModal(null);
  }
  function handleConvertQuote(q) {
    let client = clients.find(c => c.id === q.clientId) || clients.find(c => c.nombre.trim().toLowerCase() === (q.clienteNombre || '').trim().toLowerCase());
    if (!client) client = createClient({ nombre: q.clienteNombre, telefono: '', instagram: '' });
    let workingOrders = orders;
    const created = [];
    q.prendas.forEach(p => {
      const totals = computePrendaTotals(p);
      const primerTela = p.itemsConUnidad.find(i => i.categoria === 'Tela' && i.nombre);
      const newOrder = {
        id: uid(), codigo: nextCode(workingOrders, 'codigo', 'KAWA'), clientId: client.id,
        tipo: 'Personalizado', coleccionId: '', prendaCatalogoId: '',
        prenda: p.nombre, categoria: '', talla: '', tela: primerTela?.nombre || '', color: '',
        precio: Math.round(totals.totalPrenda), abono: 0, fechaEntrega: '', etapa: 'Moldería',
        prioridad: 'Media', observaciones: `Generado desde la cotización del ${fmtDate(q.fecha)}.`,
        foto: '', fotos: [], metros: '', cierre: 'No', corteResponsable: '', ensambleResponsable: '',
        costos: {
          itemsConUnidad: p.itemsConUnidad.map(it => ({ ...it, valorReal: '', factura: '' })),
          itemsDirectos: p.itemsDirectos.map(it => ({ ...it, valorReal: '', factura: '' })),
          corte: p.corte, corteReal: '', corteFactura: '',
          ensamble: p.ensamble, ensambleReal: '', ensambleFactura: '',
        },
        createdAt: new Date().toISOString(),
      };
      workingOrders = [...workingOrders, newOrder];
      created.push(newOrder);
    });
    saveOrders(workingOrders);
    saveQuotes(quotes.map(x => x.id === q.id ? { ...x, estado: 'Convertida a pedido', orderIds: created.map(o => o.id) } : x));
    setQuoteModal(null);
    setTab('pedidos');
  }

  function goTab(t, sub) { setTab(t); if (sub) setMasSub(sub); }

  function handleLogin(pw) {
    if (pw === authPassword) { setAuthed(true); setAuthError(''); }
    else { setAuthError('Contraseña incorrecta'); }
  }

  async function changePassword(current, next) {
    if (current !== authPassword) return false;
    setAuthPassword(next);
    await persist('kawa-auth', { password: next, passwordAvanzada: advancedPassword });
    return true;
  }
  async function changePasswordAvanzada(current, next) {
    if (current !== advancedPassword) return false;
    setAdvancedPassword(next);
    await persist('kawa-auth', { password: authPassword, passwordAvanzada: next });
    return true;
  }

  const NAV = [
    { key: 'inicio', label: 'Inicio', icon: Home },
    { key: 'pedidos', label: 'Pedidos', icon: ClipboardList },
    { key: 'produccion', label: 'Producción', icon: Scissors },
    { key: 'clientes', label: 'Clientes', icon: Users },
    { key: 'mas', label: 'Más', icon: Wallet },
  ];

  if (loading) {
    return (
      <div className="min-h-screen w-full relative flex items-center justify-center overflow-hidden font-body" style={{ background: BG_GRADIENT }}>
        <style>{FONT_FACES}</style>
        <ParticlesBackground />
        <p className="relative font-script" style={{ zIndex: 10, color: C.ink, textShadow: '0 1px 4px rgba(255,255,255,0.6), 0 0 12px rgba(255,255,255,0.4)', fontSize: '21px' }}>Cargando Kawa…</p>
      </div>
    );
  }

  if (!authed) {
    return <LoginScreen onSubmit={handleLogin} error={authError} />;
  }

  const commonProps = { orders, clients, onOpenOrder: setOrderDetail };

  return (
    <div className="min-h-screen w-full relative overflow-hidden font-body" style={{ background: BG_GRADIENT }}>
      <style>{FONT_FACES}</style>
      <ParticlesBackground />

      {/* Envoltorio de toda la app, por encima de las partículas */}
      <div className="relative min-h-screen md:flex" style={{ zIndex: 10 }}>
        {/* Sidebar — tablet y escritorio (misma proporción en todos los tamaños ≥ md) */}
        <aside
          className={`hidden md:flex md:flex-col flex-shrink-0 sticky top-0 h-screen transition-all duration-200 ${sidebarOpen ? 'md:w-64 lg:w-72' : 'md:w-[76px]'}`}
          style={{
            background: 'rgba(255,235,247,0.85)',
            backdropFilter: 'blur(14px)',
            WebkitBackdropFilter: 'blur(14px)',
            borderRight: `1px solid rgba(255,255,255,0.5)`,
          }}
        >
          <div className="flex items-center justify-between px-5 pt-6 pb-5">
            {sidebarOpen && <img src={LOGO_URL} alt="Kawa Moda" className="h-7 lg:h-8 w-auto object-contain" />}
            <button
              onClick={() => setSidebarOpen(s => !s)}
              className="w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0"
              style={{ background: C.line }}
              title={sidebarOpen ? 'Ocultar menú' : 'Mostrar menú'}
            >
              {sidebarOpen ? <ChevronLeft size={16} style={{ color: C.ink }} /> : <ChevronRight size={16} style={{ color: C.ink }} />}
            </button>
          </div>
          <nav className="flex-1 px-3 overflow-y-auto">
            {NAV.map(n => (
              <button
                key={n.key}
                onClick={() => setTab(n.key)}
                title={n.label}
                className={`w-full flex items-center gap-3 rounded-xl px-3.5 py-3 mb-1.5 transition-colors ${sidebarOpen ? '' : 'justify-center'}`}
                style={{ background: tab === n.key ? C.pink : 'transparent', boxShadow: tab === n.key ? '0 6px 16px -6px rgba(218,64,137,0.5)' : 'none' }}
              >
                <n.icon size={18} color={tab === n.key ? '#fff' : C.inkSoft} />
                {sidebarOpen && <span className="text-sm font-medium font-body" style={{ color: tab === n.key ? '#fff' : C.ink }}>{n.label}</span>}
              </button>
            ))}
          </nav>
          <div className="px-5 pb-5 pt-2 text-[11px] font-body" style={{ color: C.inkSoft }}>
            {sidebarOpen && 'Kawa · Atelier'}
          </div>
        </aside>

        {/* Contenido principal — llena todo el ancho disponible junto al menú, sin dejar espacio en blanco */}
        <div className="flex-1 min-w-0 flex flex-col min-h-screen">
          <div className="w-full px-4 sm:px-6 md:px-8 lg:px-10 xl:px-14 2xl:px-20 py-0 md:py-6 flex-1 flex flex-col w-full">
            <header className="pt-6 pb-4 flex items-center justify-between flex-shrink-0">
              <div>
                <img src={LOGO_URL} alt="Kawa Moda" className="h-8 w-auto object-contain mb-1.5 md:hidden rounded-md" />
                <p className="text-sm md:text-base mt-0.5 font-script" style={{ color: C.ink, textShadow: '0 1px 3px rgba(255,255,255,0.55), 0 0 10px rgba(255,255,255,0.35)', fontSize: '18px' }}>
                  {{ inicio: 'Panel de control', pedidos: 'Pedidos', produccion: 'Tablero de producción', clientes: 'Clientes', mas: 'Metas · Pagos · Cotizar · Colecciones' }[tab]}
                </p>
              </div>
              <div className="w-10 h-9 rounded-lg md:hidden flex items-center justify-center overflow-hidden bg-white/70 p-1" style={{ boxShadow: '0 4px 12px -2px rgba(122,17,82,0.5)' }}>
                <img src={LOGO_URL} alt="" className="w-full h-full object-contain" />
              </div>
            </header>

            {saveError && (
              <div className="mb-3 px-3 py-2 rounded-xl text-xs flex items-center gap-2 flex-shrink-0" style={{ background: '#F7E6E1', color: C.brick }}>
                <AlertTriangle size={14} /> {saveError}
              </div>
            )}

            <main className="pb-28 md:pb-12 flex-1 w-full">
              {tab === 'inicio' && <Inicio orders={orders} clients={clients} catalog={catalog} goals={goals} onOpenOrder={setOrderDetail} goTab={goTab} />}
              {tab === 'pedidos' && <Pedidos {...commonProps} onNew={() => setOrderModal({ mode: 'new' })} />}
              {tab === 'produccion' && <Produccion {...commonProps} />}
              {tab === 'clientes' && <Clientes clients={clients} orders={orders} onSelect={setClientDetail} onNew={() => setClientModal({ mode: 'new' })} />}
              {tab === 'mas' && <Mas sub={masSub} setSub={setMasSub} orders={orders} clients={clients} onOpenOrder={setOrderDetail} lists={lists} onListsChange={saveLists} onChangePassword={changePassword} passwordAvanzada={advancedPassword} onChangePasswordAvanzada={changePasswordAvanzada} quotes={quotes} onOpenQuote={q => setQuoteModal({ mode: 'edit', quote: q })} onNewQuote={() => setQuoteModal({ mode: 'new' })} onSaveMedidas={updateClientMedidas} catalog={catalog} onCatalogChange={saveCatalog} goals={goals} onGoalsChange={saveGoals} transactions={transactions} onTransactionsChange={saveTransactions} gastosFijos={gastosFijos} onGastosFijosChange={saveGastosFijos} ahorros={ahorros} onAhorrosChange={saveAhorros} telasCatalogo={telasCatalogo} onTelasCatalogoChange={saveTelasCatalogo} inspiracionFotos={inspiracionFotos} onInspiracionFotosChange={saveInspiracionFotos} pinterestTableros={pinterestTableros} onPinterestTablerosChange={savePinterestTableros} />}
            </main>
          </div>
        </div>

        {/* bottom nav — solo celular */}
        <nav className="fixed bottom-0 left-0 right-0 z-20 md:hidden" style={{ background: 'rgba(255,255,255,0.92)', backdropFilter: 'blur(10px)', WebkitBackdropFilter: 'blur(10px)', borderTop: `1px solid ${C.line}` }}>
          <div className="max-w-md mx-auto flex">
            {NAV.map(n => (
              <button key={n.key} onClick={() => setTab(n.key)} className="flex-1 flex flex-col items-center gap-0.5 py-2.5">
                <n.icon size={20} color={tab === n.key ? C.wine : C.inkSoft} />
                <span className="text-[10px] font-medium" style={{ color: tab === n.key ? C.wine : C.inkSoft }}>{n.label}</span>
              </button>
            ))}
          </div>
        </nav>

      {/* Order detail sheet */}
      {orderDetail && (
        <Sheet title="Pedido" onClose={() => setOrderDetail(null)}>
          <OrderDetail
            order={orderDetail}
            client={clients.find(c => c.id === orderDetail.clientId)}
            onClose={() => setOrderDetail(null)}
            onEdit={() => { setOrderModal({ mode: 'edit', order: orderDetail }); setOrderDetail(null); }}
            onStageChange={etapa => handleStageChange(orderDetail, etapa)}
            onOpenCosts={() => setOrderCostsModal(orderDetail)}
          />
        </Sheet>
      )}

      {/* Order form sheet */}
      {orderModal && (
        <Sheet title={orderModal.mode === 'edit' ? 'Editar pedido' : 'Nuevo pedido'} onClose={() => setOrderModal(null)}>
          <OrderForm
            initial={orderModal.mode === 'edit' ? orderModal.order : null}
            clients={clients}
            lists={lists}
            orders={orders}
            catalog={catalog}
            onSave={handleSaveOrder}
            onCancel={() => setOrderModal(null)}
            onDelete={handleDeleteOrder}
            onCreateClient={createClient}
          />
        </Sheet>
      )}

      {/* Client detail sheet */}
      {clientDetail && (
        <Sheet title="Clienta" onClose={() => setClientDetail(null)}>
          <ClientDetail
            client={clientDetail}
            orders={orders}
            quotes={quotes}
            onClose={() => setClientDetail(null)}
            onEdit={() => { setClientModal({ mode: 'edit', client: clientDetail }); setClientDetail(null); }}
            onOpenOrder={o => { setClientDetail(null); setOrderDetail(o); }}
          />
        </Sheet>
      )}

      {/* Client form sheet */}
      {clientModal && (
        <Sheet title={clientModal.mode === 'edit' ? 'Editar clienta' : 'Nueva clienta'} onClose={() => setClientModal(null)}>
          <ClientForm
            initial={clientModal.mode === 'edit' ? clientModal.client : null}
            onSave={handleSaveClient}
            onCancel={() => setClientModal(null)}
            onDelete={handleDeleteClient}
          />
        </Sheet>
      )}

      {/* Quote editor sheet */}
      {quoteModal && (
        <Sheet title={quoteModal.mode === 'edit' ? 'Editar cotización' : 'Nueva cotización'} onClose={() => setQuoteModal(null)}>
          <QuoteEditor
            initial={quoteModal.mode === 'edit' ? quoteModal.quote : null}
            lists={lists}
            clients={clients}
            onSave={handleSaveQuote}
            onDelete={handleDeleteQuote}
            onConvert={handleConvertQuote}
            onClose={() => setQuoteModal(null)}
            onCreateClient={createClient}
          />
        </Sheet>
      )}

      {/* Order real-costs sheet */}
      {orderCostsModal && (
        <Sheet title="Costos reales" onClose={() => setOrderCostsModal(null)}>
          <OrderCostsEditor
            order={orderCostsModal}
            onSave={(costos) => {
              saveOrders(orders.map(o => o.id === orderCostsModal.id ? { ...o, costos } : o));
              setOrderCostsModal(null);
            }}
            onClose={() => setOrderCostsModal(null)}
          />
        </Sheet>
      )}
      </div>
    </div>
  );
}
